let lastSeq = 0;
// 0.23.0: the sync cursor moves only with sync pages. lastSeq also moves when this device sends, and using it as the
// cursor skipped a message someone else sent just before ours (seen with 3+ people typing at once).
let syncSeq = 0;
let goneSeq = 0;
let editSeq = 0;
let totpSetup = false;
let raw = [];
const rawById = new Map();   // 26.10.8 perf: id -> row in raw (raw only grows, by push in remember())
let logVer = 0;
/* 26.10.8 perf: local history cache. Every message row this device has (ciphertext, exactly as the server sent it;
   nothing decrypted is stored) plus the sync cursors live in IndexedDB "bc-history", per account. A reload starts from
   there and asks the server only for what changed since (it used to re-download the whole history: 256 syncs / 55 MB
   for a big account). Groundwork for offline reading. Cleared on logout and when another account signs in here. */
const histDirty = new Set();
let histUser = "";
function histDb() {
  if (!histDb.p) histDb.p = new Promise((resolve, reject) => {
    const req = indexedDB.open("bc-history", 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains("rows")) db.createObjectStore("rows", {keyPath: "id"});
      if (!db.objectStoreNames.contains("meta")) db.createObjectStore("meta");
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
  return histDb.p;
}
function histReq(r) { return new Promise((resolve, reject) => { r.onsuccess = () => resolve(r.result); r.onerror = () => reject(r.error); }); }
async function histClear() {
  try {
    const db = await histDb();
    const tx = db.transaction(["rows", "meta"], "readwrite");
    tx.objectStore("rows").clear(); tx.objectStore("meta").clear();
    await new Promise((resolve) => { tx.oncomplete = tx.onerror = tx.onabort = resolve; });
  } catch (err) { /* no storage: nothing to clear */ }
}
async function histLoad(user) {
  // Before the first sync: fill raw and the cursors from the cache when it belongs to this account.
  if (!user || !window.indexedDB) return 0;
  histUser = user;
  try {
    const db = await histDb();
    const meta = await histReq(db.transaction("meta").objectStore("meta").get("cur"));
    if (!meta || meta.user !== user || meta.v !== 1) { await histClear(); return 0; }
    const rows = await histReq(db.transaction("rows").objectStore("rows").getAll());
    rows.sort((a, b) => a.seq - b.seq);
    for (const msg of rows) {
      if (rawById.has(msg.id)) continue;
      raw.push(msg); rawById.set(msg.id, msg);
      if (msg.seq > lastSeq) lastSeq = msg.seq;
    }
    syncSeq = Math.max(syncSeq, meta.syncSeq || 0);
    goneSeq = Math.max(goneSeq, meta.goneSeq || 0);
    editSeq = Math.max(editSeq, meta.editSeq || 0);
    histDirty.clear();
    return rows.length;
  } catch (err) {
    return 0;
  }
}
let histSaving = false;
async function histSave() {
  if (!histUser || histSaving || !window.indexedDB || !state.me || state.me.username !== histUser) return;
  histSaving = true;
  try {
    const ids = [...histDirty]; histDirty.clear();
    const db = await histDb();
    const tx = db.transaction(["rows", "meta"], "readwrite");
    const st = tx.objectStore("rows");
    for (const id of ids) { const m = rawById.get(id); if (m) st.put(m); }
    tx.objectStore("meta").put({v: 1, user: histUser, syncSeq, goneSeq, editSeq, at: Date.now()}, "cur");
    await new Promise((resolve, reject) => { tx.oncomplete = resolve; tx.onerror = tx.onabort = () => reject(tx.error); });
  } catch (err) {
    /* quota or private mode: keep working from memory */
  } finally {
    histSaving = false;
  }
}              // 26.10.8 perf: bumped when a row is deleted or edited (replaces scanning raw each render)
