function readMode() {
  const stored = localStorage.getItem("huzz-chat-mode") || localStorage.getItem("huzz-chat-theme") || "system";
  return stored === "light" || stored === "dark" ? stored : "system";
}

function schemeFor(mode) {
  if (mode === "dark") return "dark";
  if (mode === "light") return "light";
  return matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
}

function applyMode(value) {
  const mode = value === "light" || value === "dark" || value === "system" ? value : readMode();
  const root = document.documentElement;
  const auto = autoNightOn();
  const scheme = auto ? nightScheme() : schemeFor(mode);
  root.dataset.mode = mode;
  root.dataset.scheme = scheme;
  localStorage.setItem("huzz-chat-mode", mode);
  localStorage.setItem("huzz-chat-theme", mode);
  const systemBtn = $("mode-system");
  if (systemBtn) {
    systemBtn.setAttribute("aria-pressed", scheme === "dark" ? "true" : "false");
    systemBtn.textContent = scheme === "dark" ? "Disable dark mode" : "Enable dark mode";
  }
  const toggle = $("mode-toggle");
  if (toggle) {
    const dark = scheme === "dark";
    toggle.setAttribute("aria-checked", dark ? "true" : "false");
    toggle.setAttribute("aria-label", "Dark mode");   // menu-reorg: fixed name; aria-checked carries on/off
  }
}

// 0.22.3: per-chat themes (feedback: "themes can be set individually based upon the chat that you're in").
// Picking a theme while a chat is open saves it for that chat only; chats without their own pick use the app-wide
// theme, which is what you pick from the home screen or with "Use for all chats". Saved on this device.
const CHAT_PAL_KEY = "huzz-chat-palette-by-chat";
function chatPalMap() { try { const m = JSON.parse(localStorage.getItem(CHAT_PAL_KEY) || "{}"); return m && typeof m === "object" ? m : {}; } catch (err) { return {}; } }
// 0.23.0: one chat key for every kind of room: "lobby", "dm:<user>", "g:<group id>". Used for unread, alerts, themes.
function roomKey(r) {
  const x = r || room;
  if (!x || x.box === "none") return "";
  if (x.box === "lobby") return "lobby";
  if (x.box === "group") return x.gid ? "g:" + x.gid : "";
  return x.peer ? "dm:" + x.peer : "";
}
function roomFromKey(key) {
  if (key === "lobby") return {box: "lobby", peer: ""};
  if (typeof key !== "string") return null;
  if (/^g:[0-9a-f]{32}$/.test(key)) return {box: "group", peer: "", gid: key.slice(2)};
  if (key.indexOf("dm:") === 0 && key.length > 3 && key.length < 80) return {box: "dm", peer: key.slice(3)};
  return null;
}
// A group from the latest sync by id, or null.
function groupById(gid) { return (state.groups || []).find((g) => g.id === gid) || null; }
// A group's decrypted name on this device ("Group" until it can be opened).
function groupName(gid) { const n = groupNames.get(gid); return (n && n.name) || "Group"; }
function roomPalKey() { return roomKey(); }
function okPal(p) { return PALETTES.indexOf(p) >= 0 ? p : ""; }
function applyPalette(value) {
  const map = chatPalMap(), ck = roomPalKey(), pick = okPal(value || "");
  if (pick && ck) { map[ck] = pick; localStorage.setItem(CHAT_PAL_KEY, JSON.stringify(map)); }
  else if (pick) localStorage.setItem("huzz-chat-palette", pick);
  const global = okPal(localStorage.getItem("huzz-chat-palette") || "") || "huzz";
  const own = ck ? okPal(map[ck] || "") : "";
  const palette = own || global;
  document.documentElement.dataset.palette = palette;
  document.querySelectorAll("#palette-choices button").forEach((button) => {
    button.setAttribute("aria-pressed", button.dataset.palette === palette ? "true" : "false");
  });
  const note = $("palette-scope"), all = $("palette-all");
  if (note) note.textContent = !ck ? "Your theme for every chat. Open a chat to give it its own." : own ? "This chat has its own theme." : "This chat uses your main theme. Pick one to give it its own.";
  if (all) all.hidden = !ck || !own;
}
function paletteForAll() {
  const p = okPal(document.documentElement.dataset.palette || "") || "huzz";
  localStorage.setItem("huzz-chat-palette", p);
  localStorage.removeItem(CHAT_PAL_KEY);
  applyPalette();
}

function applyTextSize(value) {
  const size = value || localStorage.getItem("huzz-chat-text") || "medium";
  const next = size === "small" || size === "large" ? size : "medium";
  document.documentElement.dataset.text = next;
  document.querySelectorAll("#text-size-choices button").forEach((button) => {
    button.setAttribute("aria-pressed", button.dataset.size === next ? "true" : "false");
  });
  localStorage.setItem("huzz-chat-text", next);
}

const NAME_PALETTE = ["#f2c94c", "#f2994a", "#ff7a7a", "#ff6fb5", "#d68cff", "#a78bfa", "#7aa2ff", "#56ccf2", "#4dd9c6", "#6fcf97", "#a6e35f", "#e0c097", "#c9d1d9", "#ffd6a5"];

function nameColor(name) {
  const map = (state && state.name_colors) || {};
  const c = name && map[name];
  return (typeof c === "string" && /^#[0-9a-f]{6}$/.test(c)) ? c : "";
}

function paintName(el, name) {
  el.classList.add("dname");
  el.style.color = nameColor(name);
  return el;
}

function nameSpan(name) {
  const span = document.createElement("span");
  span.textContent = dn(name);
  return paintName(span, name);
}

function dn(name) {
  // 26.10.5: a nickname you gave this friend wins (only you see it), then their own display name, then the username.
  const nick = (state && state.nicknames) || {};
  if (name && typeof nick[name] === "string" && nick[name]) return nick[name];
  const map = (state && state.display_names) || {};
  return (name && map[name]) || name || "";
}

// 26.10.5: the friend's own name, ignoring any nickname you gave them (shown small on their profile card).
function ownName(name) {
  const map = (state && state.display_names) || {};
  return (name && map[name]) || name || "";
}

async function api(path, options) {
  let res;
  try {
    res = await fetch(path, options);
  } catch (err) {
    const error = new Error("The page could not reach BranchChat.");
    error.network = true;
    throw error;
  }
  if (res.status === 401) {
    location.replace("/");
    throw new Error("Sign in first.");
  }
  const type = res.headers.get("content-type") || "";
  if (!type.includes("json")) {
    if (!res.ok) throw new Error("The page could not reach BranchChat.");
    return res;
  }
  const data = await res.json();
  if (!res.ok) {
    const error = new Error(data.error || "That did not work.");
    error.status = res.status;
    error.data = data;
    throw error;
  }
  return data;
}

function post(path, body) {
  return api(path, {
    method: "POST",
    headers: {"Content-Type": "application/json"},
    body: JSON.stringify(body),
  });
}

function idb() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open("huzz-chat", 1);
    req.onupgradeneeded = () => req.result.createObjectStore("kv");
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function idbGet(key) {
  const db = await idb();
  return new Promise((resolve, reject) => {
    const req = db.transaction("kv").objectStore("kv").get(key);
    req.onsuccess = () => resolve(req.result || null);
    req.onerror = () => reject(req.error);
  });
}

// 26.10.2: remove one entry from this browser's key store (used to clear per-chat backgrounds).
async function idbDel(key) {
  const db = await idb();
  return new Promise((resolve, reject) => {
    const req = db.transaction("kv", "readwrite").objectStore("kv").delete(key);
    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

async function idbSet(key, value) {
  const db = await idb();
  return new Promise((resolve, reject) => {
    const req = db.transaction("kv", "readwrite").objectStore("kv").put(value, key);
    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

// Every key name in this browser's key store (used to find message keys set aside for other accounts).
async function idbKeys() {
  const db = await idb();
  return new Promise((resolve, reject) => {
    const req = db.transaction("kv").objectStore("kv").getAllKeys();
    req.onsuccess = () => resolve(req.result || []);
    req.onerror = () => reject(req.error);
  });
}

/* 26.10.2 fix: the account name in the bottom-left bar stayed on the placeholder word "Account".
   Why: this browser keeps one message key (IndexedDB "device"). When a second account is made or used in the same
   browser, that key still belongs to the first account, so the server turns it down (400). The app used to stop right
   there, before its first sync, so the bar never got the name and no chats loaded.
   Now: when the server turns the key down, the key is set aside under "device-<its id>" (nothing is thrown away, so the
   other account still finds it next time), any key set aside earlier is tried, and if none fits, a fresh key is made
   for the account signed in now. A network problem is not treated as "turned down"; it still shows the usual note. */
async function registerDevice() {
  const send = async (dev) => post("/api/devices", {device_id: dev.deviceId, public_key: await exportPublic(dev.publicKey)});
  try {
    await send(device);
    return;
  } catch (err) {
    if (err.network || err.status !== 400) throw err;
  }
  const refused = device;
  await idbSet("device-" + refused.deviceId, refused);
  let keys = [];
  try { keys = await idbKeys(); } catch (err) { keys = []; }
  for (const name of keys) {
    if (typeof name !== "string" || !name.startsWith("device-") || name === "device-" + refused.deviceId) continue;
    const spare = await idbGet(name);
    if (!spare || !spare.deviceId || !spare.privateKey) continue;
    try {
      await send(spare);          // this account's own key from an earlier visit: use it again
      device = spare;
      await idbSet("device", device);
      return;
    } catch (err) {
      if (err.network || err.status !== 400) throw err;
    }
  }
  device = await createIdentity();  // no key here belongs to this account yet: make one
  await idbSet("device", device);
  await send(device);
}

function explain(text) {
  $("upload-reason").textContent = text;
  if (!$("upload-dialog").open) $("upload-dialog").showModal();
}

function note(text) {
  $("send-note").textContent = text || "";
}

function lockSvg() {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("viewBox", "0 0 16 16");
  svg.setAttribute("aria-hidden", "true");
  const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
  path.setAttribute("d", "M8 1.7a2.8 2.8 0 0 0-2.8 2.8V7H4.4A1.4 1.4 0 0 0 3 8.4v4.7A1.4 1.4 0 0 0 4.4 14.5h7.2a1.4 1.4 0 0 0 1.4-1.4V8.4A1.4 1.4 0 0 0 11.6 7h-.8V4.5A2.8 2.8 0 0 0 8 1.7zm0 1.5a1.3 1.3 0 0 1 1.3 1.3V7H6.7V4.5A1.3 1.3 0 0 1 8 3.2zm.7 6.6v2.1H7.3V9.8a.9.9 0 1 1 1.4 0z");
  svg.append(path);
  return svg;
}

function statusLed(online, encrypted) {
  const led = document.createElement("span");
  led.className = "led" + (online ? " on" : "") + (encrypted ? " locked" : "");
  const label = (online ? "Online" : "Offline") + ", " + (encrypted ? "end-to-end encrypted" : "not encrypted");
  led.title = label;
  led.setAttribute("aria-label", label);
  if (encrypted) led.append(lockSvg());
  return led;
}

/* fix-avatar-refresh: profile pictures are versioned. /api/sync carries {username: version} ("avatars"); the server
   bumps /api/wait when anyone changes their picture, so every open page hears about it on the channel it already
   holds. A same-URL <img> is never re-fetched inside one page (browsers keep a per-document image list), which is
   why a friend's new picture used to stay stale until a full reload. Now a new version means a new URL: it is
   preloaded off-screen and swapped into every <img data-av=name> once decoded, so there is no flicker. */
const avatarVers = new Map();   // username -> version seen in the last sync
function avatarUrl(username) {
  const v = avatarVers.get(username);
  return "/api/avatar?u=" + encodeURIComponent(username) + (v ? "&v=" + v : "");
}
function avatarVersionsChanged(next) {
  const changed = [];
  for (const [name, v] of Object.entries(next)) {
    // After the first sync, a name that is new to the map is someone who just added a picture.
    if (avatarVersionsChanged.primed ? avatarVers.get(name) !== v : false) changed.push(name);
    avatarVers.set(name, v);
  }
  avatarVersionsChanged.primed = true;
  for (const name of changed) loadAvatar(name);
}

/* fix-avatar-flicker: every picture is fetched ONCE per (person, version) into an in-memory blob: URL. Every <img>
   for that person (sidebar rows, group clusters, rebuilt on each sync tick) points at that blob URL, which the
   browser already holds decoded, so a rebuilt row paints the photo in its first frame instead of an empty <img>
   (the old /api/avatar answers were no-store, so each new or cloned <img> went back to the network and showed the
   initial until it arrived). Only a real 404 means "no picture"; a 429, 5xx or dropped request keeps the last
   good photo and retries later. A new version keeps showing the old photo until the new one is decoded. */
const avatarBlobs = new Map();  // "name|version" -> {state: "pending"|"ok"|"none", url}
const avatarLast = new Map();   // name -> last good blob URL (what new elements show)
const avatarNone = new Set();   // names whose current version truly has no picture
function avatarPaint(name) {
  const url = avatarLast.get(name);
  for (const el of document.querySelectorAll("img[data-av]")) {
    if (el.dataset.av !== name) continue;
    if (url) { if (el.src !== url) el.src = url; el.hidden = false; }
    else if (avatarNone.has(name)) {
      if (el.dataset.kind === "face") el.remove(); else el.src = "/static/maple-leaf.svg?v=1";
    }
  }
}
function loadAvatar(name) {
  const key = name + "|" + (avatarVers.get(name) || "");
  if (avatarBlobs.has(key)) return;
  const entry = {state: "pending", url: ""};
  avatarBlobs.set(key, entry);
  fetch(avatarUrl(name), {credentials: "same-origin"}).then(async (r) => {
    if (r.status === 404) { entry.state = "none"; if (!avatarLast.has(name)) avatarNone.add(name); avatarPaint(name); return; }
    if (!r.ok) throw new Error("avatar " + r.status);
    const url = URL.createObjectURL(await r.blob());
    const probe = new Image(); probe.src = url;
    try { await probe.decode(); } catch (e) { URL.revokeObjectURL(url); throw e; }
    entry.state = "ok"; entry.url = url;
    const old = avatarLast.get(name);
    avatarLast.set(name, url); avatarNone.delete(name);
    avatarPaint(name);
    if (old && old !== url) setTimeout(() => URL.revokeObjectURL(old), 60000);
  }).catch(() => {
    // Transient (rate limit, server error, network drop): forget the attempt so a later render retries.
    avatarBlobs.delete(key);
    setTimeout(() => { if (!avatarBlobs.has(key)) loadAvatar(name); }, 15000);
  });
}
const avatarPool = new Map();  // name -> recent <img>s; a detached one that already shows the current photo is reused
// Rows are built detached and attached afterwards, so "not connected" alone does not mean free: an <img> handed out
// in the current synchronous build carries this build's number and is skipped until the next task.
let avatarGen = 0, avatarGenTick = false;
function avatarClaim(el) {
  if (!avatarGenTick) { avatarGenTick = true; queueMicrotask(() => { avatarGen++; avatarGenTick = false; }); }
  el.__avGen = avatarGen;
  return el;
}
function avatarEl(username, kind) {
  const pool = avatarPool.get(username) || [];
  avatarPool.set(username, pool);
  const want = avatarLast.get(username);
  const spare = want && pool.find((el) => !el.isConnected && el.dataset.kind === kind && el.src === want && el.complete && el.__avGen !== avatarGen);
  if (spare) {
    // Re-attaching an already-decoded <img> paints in the same frame, even in Android WebView.
    spare.hidden = false;
    pool.splice(pool.indexOf(spare), 1); pool.push(spare);
    return avatarClaim(spare);
  }
  const img = avatarClaim(document.createElement("img"));
  pool.push(img);
  if (pool.length > 24) { const i = pool.findIndex((el) => !el.isConnected); pool.splice(i < 0 ? 0 : i, 1); }
  img.alt = ""; img.decoding = "sync"; img.dataset.av = username; img.dataset.kind = kind;
  const url = avatarLast.get(username);
  if (url) img.src = url;
  else if (avatarNone.has(username) && kind !== "face") img.src = "/static/maple-leaf.svg?v=1";
  else { img.hidden = true; loadAvatar(username); }
  return img;
}
function avatarImg(username) {
  const img = avatarEl(username, "pfp");
  img.width = 36; img.height = 36;
  return img;
}

function personPic(username, online, encrypted) {
  const wrap = document.createElement("span");
  wrap.className = "pfp" + (online ? " on" : "");
  const label = (online ? "Online" : "Offline") + ", " + (encrypted ? "end-to-end encrypted" : "not encrypted");
  wrap.title = username + ": " + label;
  wrap.setAttribute("aria-label", label);
  // Reuse one loaded <img> per person. The sidebar is rebuilt on every sync, and a
  // fresh <img> each time re-fetched the picture and flashed its placeholder.
  wrap.append(avatarImg(username));
  // 0.21.08.1: no lock badge on profile pictures any more (it doubled up with the lock next to the name). The label above
  // still says whether the chat is end-to-end encrypted.
  return wrap;
}

function setSecure(on) {
  const led = $("secure-led");
  if (!led) return;
  const ready = !!on && window.isSecureContext;
  const changed = ready !== secureReady;
  secureReady = ready;
  led.classList.toggle("on", ready);
  led.classList.toggle("locked", ready);
  $("secure-text").textContent = ready ? "End-to-end encrypted chat" : "Not encrypted";
  const old = led.querySelector("svg");
  if (old) old.remove();
  if (ready) led.append(lockSvg());
  if (changed) {
    paintKey = "";
    maybeRender();
  }
}

function placeDock() {
  const dock = $("composer");
  if (!dock) return;
  document.documentElement.style.setProperty("--dock", dock.offsetHeight + "px");
}

function nameList(names) {
  if (names.length === 1) return names[0];
  if (names.length === 2) return names[0] + " and " + names[1];
  return names.slice(0, -1).join(", ") + ", and " + names[names.length - 1];
}

function whoLine() {
  return "";
}

// smooth-transitions: one shared date formatter each. toLocaleDateString/toLocaleTimeString with options build a new
// formatter on every call, and opening a long chat formats hundreds of times; this made each chat switch stall
// (about a third of the switch time in our profile). Same text as before.
const monthFmt = new Intl.DateTimeFormat(undefined, {month: "long"});
const clockFmt = new Intl.DateTimeFormat(undefined, {hour: "numeric", minute: "2-digit"});
function dayLabel(ts) {
  const date = new Date(ts * 1000);
  const d = date.getDate();
  const suffix = (d % 100 >= 11 && d % 100 <= 13) ? "th" : ({1: "st", 2: "nd", 3: "rd"}[d % 10] || "th");
  let label = monthFmt.format(date) + " " + d + suffix;
  if (date.getFullYear() !== new Date().getFullYear()) label += ", " + date.getFullYear();
  return label;
}

function clock(ts) {
  return clockFmt.format(new Date(ts * 1000));
}

function inRoom(msg) {
  if (room.box === "lobby") return msg.box === "lobby";
  if (room.box === "group") return msg.box === "group" && msg.g === room.gid;
  return msg.box === "dm" && msg.peer === room.peer;
}

async function wrapDevice(target, keyBytes) {
  const pub = await importPublic(target.public_key);
  const wrapped = await wrapFor(pub, keyBytes);
  return {device_id: target.device_id, ...wrapped};
}

async function epochKeyFor(epoch) {
  if (epochKeys.has(epoch)) return epochKeys.get(epoch);
  const wrap = (state.lobby.wraps || []).find((item) => item.epoch === epoch && item.device_id === device.deviceId);
  if (!wrap) return null;
  const raw = await unwrap(device.privateKey, wrap);
  if (raw.length !== 32) return null;
  epochKeys.set(epoch, raw);
  return raw;
}

// The group key for one epoch, unwrapped with this device's key and cached; null if this device has no wrap.
async function groupKeyFor(gid, epoch) {
  const k = gid + ":" + epoch;
  if (groupKeys.has(k)) return groupKeys.get(k);
  const g = groupById(gid);
  const wrap = g && (g.wraps || []).find((item) => item.epoch === epoch && item.device_id === device.deviceId);
  if (!wrap) return null;
  try {
    const bytes = await unwrap(device.privateKey, wrap);
    if (bytes.length !== 32) return null;
    groupKeys.set(k, bytes);
    return bytes;
  } catch (err) {
    return null;
  }
}

async function openMessage(msg) {
  // A tombstone has no ciphertext. Decrypting it would stall this thread. Group notices are plaintext rows.
  if (!msg || msg.deleted || msg.event) return null;
  if (plainById.has(msg.id)) return plainById.get(msg.id);
  try {
    let contentKey;
    if (msg.box === "lobby") {
      const epochKey = await epochKeyFor(msg.epoch);
      if (!epochKey) return null;
      contentKey = await decryptBytes(epochKey, msg.epoch_iv, msg.epoch_ct);
    } else if (msg.box === "group") {
      const groupKey = await groupKeyFor(msg.g, msg.epoch);
      if (!groupKey) return null;
      contentKey = await decryptBytes(groupKey, msg.epoch_iv, msg.epoch_ct);
    } else {
      const wrap = (msg.wraps || []).find((item) => item.device_id === device.deviceId);
      if (!wrap) return null;
      contentKey = await unwrap(device.privateKey, wrap);
    }
    const payload = await decryptJson(contentKey, msg.iv, msg.ct);
    const opened = {payload, contentKey};
    plainById.set(msg.id, opened);
    shareWraps(msg, contentKey);
    return opened;
  } catch (err) {
    const opened = {locked: true};
    plainById.set(msg.id, opened);
    return opened;
  }
}

async function shareWraps(msg, contentKey) {
  if (msg.box !== "dm") return;
  const names = [msg.sender, msg.peer];
  const have = new Set((msg.wraps || []).map((item) => item.device_id));
  const need = state.devices.filter((item) => names.includes(item.username) && !have.has(item.device_id));
  if (!need.length) return;
  const mark = msg.id + ":" + need.map((item) => item.device_id).join(",");
  if (shared.has(mark)) return;
  shared.add(mark);
  try {
    const wraps = [];
    for (const target of need) wraps.push(await wrapDevice(target, contentKey));
    await post("/api/messages/wraps", {id: msg.id, wraps});
    msg.wraps.push(...wraps);
  } catch (err) {
    shared.delete(mark);
  }
}

async function courier() {
  await lobbyCourier();
  await groupCourier();
}

async function lobbyCourier() {
  const now = Date.now();
  if (now - courierAt < 4000) return;
  const lobby = state.lobby;
  if (!lobby.joined) return;
  if (lobby.needs_epoch) {
    const members = new Set((lobby.members || []).map((item) => item.username));
    const targets = state.devices.filter((item) => members.has(item.username));
    if (!targets.some((item) => item.device_id === device.deviceId)) return;
    courierAt = now;
    const epochKey = crypto.getRandomValues(new Uint8Array(32));
    const wraps = [];
    for (const target of targets) wraps.push(await wrapDevice(target, epochKey));
    try {
      await post("/api/lobby/epoch", {epoch: lobby.epoch, wraps});
      epochKeys.set(lobby.epoch, epochKey);
    } catch (err) { /* another member saved the key */ }
    return;
  }
  if (!lobby.missing || !lobby.missing.length) return;
  const epochKey = await epochKeyFor(lobby.epoch);
  if (!epochKey) return;
  courierAt = now;
  const wraps = [];
  for (const target of lobby.missing) wraps.push(await wrapDevice(target, epochKey));
  try {
    await post("/api/lobby/wraps", {epoch: lobby.epoch, wraps});
  } catch (err) { /* the next poll tries again */ }
}

function dropOpened(id) {
  // Forget decrypted text and revoke a file URL so a removal does not keep the bytes.
  const opened = plainById.get(id);
  const file = opened && opened.payload && opened.payload.file;
  if (file && mediaUrl.has(file.id)) {
    URL.revokeObjectURL(mediaUrl.get(file.id));
    mediaUrl.delete(file.id);
    mediaBlob.delete(file.id);
  }
  plainById.delete(id);
}

// Mark a message removed in this browser right away (other browsers learn it from the server).
function markDeleted(id, how, own) { // how: {anim, seed} from the deleter (26.10.2), or nothing; own: this device's own tap
  // Mark a row this browser already has. The server tombstone is what other browsers see.
  const known = rawById.get(id);
  if (!known) return false;
  const already = !!known.deleted;
  // 26.10.11: "Don't show animations on other people's deletes": a message someone else sent that was deleted
  // elsewhere just goes, with no delete animation and no delete sound. Your own deletes keep theirs.
  if (!already && !(quietDel.on && !own && known.sender !== (state.me && state.me.username))) snapRow(id, how);
  known.deleted = true;
  logVer += 1;
  histDirty.add(id);
  known.iv = "";
  known.ct = "";
  known.wraps = [];
  known.blob = null;
  known.epoch_iv = "";
  known.epoch_ct = "";
  dropOpened(id);
  reactionsById.delete(id);
  for (const [key, ids] of unreadIds) {
    if (!ids.delete(id)) continue;
    const left = (unreadBy.get(key) || 0) - 1;
    if (left > 0) unreadBy.set(key, left); else unreadBy.delete(key);
    if (!ids.size) unreadIds.delete(key);
    paintTitle();
  }
  return !already;
}

function noteRemoved(data) {
  // Apply removals the message cursor cannot see, and remember how far that cursor got.
  if (!data) return;
  for (const item of data.removed || []) {
    // 26.10.2: newer servers say which animation the deleter saw (anim, seed); play that one here too.
    if (item && item.id) markDeleted(item.id, item.anim ? {anim: item.anim, seed: item.seed} : null);
    if (item && typeof item.seq === "number" && item.seq > goneSeq) goneSeq = item.seq;
  }
  if (typeof data.gone === "number" && data.gone > goneSeq) goneSeq = data.gone;
}

function noteEditCursor(value) {
  const seq = typeof value === "number" ? value : 0;
  if (seq > editSeq) editSeq = seq;
}

function applyEdited(msg) {
  // Replace ciphertext in place. seq did not move, so drop the old plaintext.
  if (!msg || !msg.id) return;
  noteEditCursor(msg.edited_seq);
  const known = rawById.get(msg.id);
  if (!known) {
    remember(msg);
    return;
  }
  if (known.deleted) return;
  const changed = known.ct !== msg.ct || (msg.edited_ts || 0) !== (known.edited_ts || 0);
  if (msg.iv) known.iv = msg.iv;
  if (msg.ct) known.ct = msg.ct;
  if (msg.edited_ts) known.edited_ts = msg.edited_ts;
  if (typeof msg.edited_seq === "number") known.edited_seq = msg.edited_seq;
  if (changed) { plainById.delete(msg.id); logVer += 1; histDirty.add(msg.id); }
}

function noteEdited(data) {
  if (!data) return;
  for (const msg of data.edited || []) applyEdited(msg);
  noteEditCursor(data.edit);
}

function syncUrl(since, react) {
  // 26.10.8: st = stamp of the people/keys/groups part we already have; the server leaves those out when unchanged.
  const st = state && state.st ? "&st=" + encodeURIComponent(state.st) : "";
  return "/api/sync?since=" + since + "&react=" + react + "&gone=" + goneSeq + "&edit=" + editSeq + st;
}

// 26.10.8 perf: a "same" answer leaves out the sections that did not change; carry them over from the last state.
const SYNC_DELTA_KEYS = ["online", "friends", "incoming", "outgoing", "devices", "lobby", "groups", "mutes", "chatlist",
  "display_names", "name_colors", "contacts", "nicknames", "avatars"];
function mergeSync(data) {
  if (data && data.same && state) {
    for (const k of SYNC_DELTA_KEYS) if (!(k in data) && k in state) data[k] = state[k];
  }
  if (data && data.avatars && typeof data.avatars === "object") avatarVersionsChanged(data.avatars);
  return data;
}

function remember(msg) {
  noteEditCursor(msg && msg.edited_seq);
  if (msg.deleted) {
    const known = rawById.get(msg.id);
    if (known) markDeleted(msg.id);
    else { raw.push(msg); rawById.set(msg.id, msg); logVer += 1; histDirty.add(msg.id); }
    if (msg.seq > lastSeq) lastSeq = msg.seq;
    return false;
  }
  const known = rawById.get(msg.id);
  if (known && known.deleted) {
    if (msg.seq > lastSeq) lastSeq = msg.seq;
    return false;
  }
  if (known) {
    if (msg.ct && (msg.edited_ts || 0) > (known.edited_ts || 0)) {
      known.iv = msg.iv;
      known.ct = msg.ct;
      known.edited_ts = msg.edited_ts;
      known.edited_seq = msg.edited_seq;
      plainById.delete(msg.id);
      logVer += 1;
      histDirty.add(msg.id);
    }
    let added = false;
    for (const wrap of msg.wraps || []) {
      if (!wrap || !wrap.device_id) continue;
      if ((known.wraps || []).some((item) => item.device_id === wrap.device_id)) continue;
      known.wraps = known.wraps || [];
      known.wraps.push(wrap);
      added = true;
    }
    if (added) {
      histDirty.add(msg.id);
      const opened = plainById.get(msg.id);
      if (!opened || opened.locked) plainById.delete(msg.id);
    }
    if (msg.seq > lastSeq) lastSeq = msg.seq;
    return false;
  }
  raw.push(msg);
  rawById.set(msg.id, msg);
  histDirty.add(msg.id);
  if (msg.seq > lastSeq) lastSeq = msg.seq;
  return true;
}

function chatKeyOf(msg) {
  if (!msg || msg.event || msg.sender === state.me.username) return "";
  if (msg.box === "lobby") return "lobby";
  if (msg.box === "group") return msg.g && groupById(msg.g) ? "g:" + msg.g : "";
  if (msg.box !== "dm") return "";
  const other = msg.sender === state.me.username ? msg.peer : msg.sender;
  return other ? "dm:" + other : "";
}

// 0.23.2: per-chat mute, kept on the server for this account (state.mutes from /api/sync: {chat key: until},
// until = unix seconds, 0 = until turned back on). Muted chats still count unread; they skip sounds and alerts.
function muteKeyNorm(key) { return key && key.indexOf("dm:") === 0 ? "dm:" + key.slice(3).toLowerCase() : (key || ""); }
function chatMuteUntil(key) {
  const m = state.mutes;
  if (!m || !key) return null;
  const k = muteKeyNorm(key);
  if (!Object.prototype.hasOwnProperty.call(m, k)) return null;
  const until = Number(m[k]);
  if (until === 0) return 0;
  return until * 1000 > Date.now() ? until : null;
}
function chatIsMuted(key) { return chatMuteUntil(key) !== null; }
function mutedKeys() { return Object.keys(state.mutes || {}).filter(chatIsMuted).sort().join(","); }

function viewing(key) {
  if (document.hidden || !document.hasFocus()) return false;
  return !!key && roomKey() === key;
}

function unreadTotal() {
  let count = 0;
  for (const n of unreadBy.values()) count += n;
  return count;
}

// 0.23.3-beta.12: keep the page's own title (the server puts the organisation's name in it when one is configured).
const BASE_TITLE = document.title || "BranchChat";
function paintTitle() {
  const count = unreadTotal();
  document.title = count ? "(" + count + ") " + BASE_TITLE : BASE_TITLE;
}

function unreadMark(count) {
  if (!count) return null;
  const badge = document.createElement("span");
  badge.className = "unread";
  badge.textContent = count > 9 ? "9+" : String(count);
  return badge;
}

function cleanPreview(text) {
  return String(text || "").replace(/[\u0000-\u001f\u007f]/g, " ").replace(/\s+/g, " ").trim();
}

function previewOf(payload, msg) {
  const text = cleanPreview(bcHook("text", payload && payload.text) ?? (payload && payload.text));
  const file = payload && payload.file;
  let extra = "";
  if (isStickerPayload(payload)) return "Sticker: " + stickerAlt(payload);   // 26.10.4: "Sticker: Bunny waving: Hi!"
  if (file && file.kind === "gif") extra = "GIF";
  else if (file && file.kind === "image") extra = "Photo";
  else if (file && file.kind === "video") extra = "Video";
  else if (file || (msg && msg.blob)) extra = "Attachment";
  let body = text;
  if (text && extra) body = text + " (" + extra + ")";
  else if (extra) body = extra;
  if (!body) body = "New message";
  if (body.length > 180) body = body.slice(0, 177) + "...";
  return body;
}

/* 0.21: home list rows, Telegram style: name + time, then a one-line preview of the
   last message. Built only from messages this device already holds and decrypted
   itself; nothing about previews goes to the server. */
function chatKeyFor(msg) {
  if (!msg) return "";
  if (msg.box === "lobby") return "lobby";
  if (msg.box === "group") return msg.g ? "g:" + msg.g : "";
  return msg.box === "dm" && msg.peer ? "dm:" + msg.peer : "";
}

function latestByChat() {
  // Preview fix: a deleted message is skipped, so the row shows the newest message that still exists
  // (and its time and sort order). A chat whose messages are all deleted reads like an empty chat.
  const out = new Map();
  for (const msg of raw) {
    if (msg.deleted) continue;
    const key = chatKeyFor(msg);
    if (!key) continue;
    const cur = out.get(key);
    if (!cur || ((msg.ts || 0) - (cur.ts || 0) || (msg.seq || 0) - (cur.seq || 0)) > 0) out.set(key, msg);
  }
  return out;
}

// Decrypt (on this device only) the message each home row previews. After a deletion this is the older
// message the row falls back to, which may not have been opened yet.
async function openPreviews() {
  const todo = [...latestByChat().values()].filter((msg) => !(msg.deleted || msg.event || plainById.has(msg.id)));
  await Promise.all(todo.map(async (msg) => {   // 26.10.8 perf: in parallel
    if (await openMessage(msg)) previewLocked.delete(msg.id);   // home previews, decrypted here only
    else previewLocked.add(msg.id);
  }));
}

// The one place preview wording is made. A future language filter can mask here.
const previewLocked = new Set();  // last messages this device has no key for
function previewText(msg, opened) {
  if (msg.event) return eventText(msg);
  if (msg.deleted) return "Message deleted";
  if (!opened) return previewLocked.has(msg.id) ? "Encrypted message" : "\u2026";
  if (opened.locked) return "Encrypted message";
  const payload = opened.payload || {};
  if (isStickerPayload(payload)) return "Sticker: " + stickerAlt(payload);   // 26.10.4
  const text = cleanPreview(bcHook("text", payload.text) ?? payload.text);
  const file = payload.file;
  if (file) {
    let label = "\ud83d\udcce " + (cleanPreview(file.name) || "File");
    if (file.kind === "gif") label = "GIF";
    else if (file.kind === "image") label = "\ud83d\udcf7 Photo";
    else if (file.kind === "video") label = "\ud83c\udfac Video";
    return text ? label + " " + text : label;
  }
  return text || "\u2026";
}

function previewParts(msg) {
  // [prefix, body]. Lobby messages from others name the sender; your own say "You".
  const body = previewText(msg, plainById.get(msg.id));
  if (msg.deleted || msg.event) return ["", body];
  if (msg.sender === state.me.username) return ["You: ", body];
  if (msg.box === "lobby" || msg.box === "group") return [dn(msg.sender) + ": ", body];
  return ["", body];
}

function rowTime(ts) {
  if (!ts) return "";
  const date = new Date(ts * 1000);
  const now = new Date();
  if (date.toDateString() === now.toDateString()) return clock(ts);
  const days = (new Date(now.getFullYear(), now.getMonth(), now.getDate()) - new Date(date.getFullYear(), date.getMonth(), date.getDate())) / 86400000;
  if (days > 0 && days < 7) return date.toLocaleDateString(undefined, {weekday: "short"});
  if (date.getFullYear() === now.getFullYear()) return date.toLocaleDateString(undefined, {month: "short", day: "numeric"});
  return date.toLocaleDateString(undefined, {year: "2-digit", month: "numeric", day: "numeric"});
}

const BELL_OFF_SVG = '<svg viewBox="0 0 24 24" width="15" height="15" aria-hidden="true" focusable="false"><path fill="currentColor" d="M12 22a2.2 2.2 0 0 0 2.2-2.2H9.8A2.2 2.2 0 0 0 12 22zm6.5-6.2V11c0-3.2-1.7-5.8-4.7-6.5v-.7a1.8 1.8 0 0 0-3.6 0v.7c-.7.2-1.3.4-1.8.8l10.1 10.5zM4.3 3 3 4.3l3.7 3.8c-.4.9-.7 1.9-.7 2.9v4.8L4 17.9V19h13.5l2.2 2.3 1.3-1.3z"/></svg>';
const BELL_SVG = '<svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true" focusable="false"><path fill="currentColor" d="M12 22a2.2 2.2 0 0 0 2.2-2.2H9.8A2.2 2.2 0 0 0 12 22zm6-6.2V11c0-3.2-1.6-5.8-4.5-6.5v-.7a1.5 1.5 0 0 0-3 0v.7C7.6 5.2 6 7.8 6 11v4.8L4 17.9V19h16v-1.1zM16 16.8H8V11c0-2.4 1.5-4.3 4-4.3s4 1.9 4 4.3z"/></svg>';
function mutedIcon() {
  const ico = document.createElement("span");
  ico.className = "muted-ico";
  ico.title = "Muted";
  ico.setAttribute("role", "img");
  ico.setAttribute("aria-label", "Muted");
  ico.innerHTML = BELL_OFF_SVG;
  return ico;
}
function chatRowMain(nameNode, msg, fallback, badge, previewId, muted) {
  const main = document.createElement("span");
  main.className = "row-main";
  const top = document.createElement("span");
  top.className = "row-top";
  nameNode.classList.add("row-name");
  const time = document.createElement("span");
  time.className = "row-time";
  time.textContent = msg ? rowTime(msg.ts) : "";
  top.append(nameNode);
  if (muted) top.append(mutedIcon());   // 0.23.2
  top.append(time);
  const bottom = document.createElement("span");
  bottom.className = "row-bottom";
  const preview = document.createElement("span");
  preview.className = "row-preview";
  if (previewId) preview.id = previewId;
  if (msg) {
    const [prefix, body] = previewParts(msg);
    if (prefix) {
      const who = document.createElement("span");
      who.className = "who";
      who.textContent = prefix;
      preview.append(who);
    }
    preview.append(document.createTextNode(body));
    preview.title = prefix + body;
  } else if (fallback) {
    if (typeof fallback === "string") preview.textContent = fallback;
    else preview.append(...fallback);
    preview.classList.add("empty");
  }
  bottom.append(preview);
  if (badge) bottom.append(badge);
  main.append(top, bottom);
  return main;
}

function b64urlToBytes(text) {
  const pad = text.length % 4 === 0 ? "" : "=".repeat(4 - (text.length % 4));
  const b64 = String(text).replace(/-/g, "+").replace(/_/g, "/") + pad;
  const raw = atob(b64);
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < out.length; i += 1) out[i] = raw.charCodeAt(i);
  return out;
}

function iosNeedsInstall() {
  const ua = navigator.userAgent || "";
  const apple = /iPad|iPhone|iPod/.test(ua) || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
  if (!apple) return false;
  const standalone = window.navigator.standalone === true || matchMedia("(display-mode: standalone)").matches;
  return !standalone;
}

function muteEpoch() {
  const choice = muteChoice();
  if (choice.mode === "until") return 4102444800;
  if (choice.until) return Math.floor(choice.until / 1000);
  return 0;
}

async function raiseSeq(seq) {
  if (!seq) return;
  const db = await idb();
  await new Promise((resolve, reject) => {
    const tx = db.transaction("kv", "readwrite");
    const store = tx.objectStore("kv");
    const req = store.get("notify-seq");
    req.onsuccess = () => {
      const current = Number(req.result) || 0;
      if (seq > current) store.put(seq, "notify-seq");
      resolve();
    };
    req.onerror = () => reject(req.error);
  });
}

async function armCursor() {
  try {
    await raiseSeq(lastSeq);
    await idbSet("notify-armed", 1);
    await idbSet("notify-mute", localStorage.getItem("huzz-chat-mute") || "");
  } catch (err) { /* the next poll tries again */ }
}

function focusMark() {
  const key = roomKey() || "dm:";
  idbSet("notify-focus", {key: key, at: Date.now()}).catch(() => {});
}

async function advanceSeen(messages) {
  let seq = Number(await idbGet("notify-seq")) || 0;
  const ordered = messages.slice().sort((a, b) => a.seq - b.seq);
  for (const msg of ordered) {
    if (!msg || msg.seq <= seq) continue;
    if (seq && msg.seq !== seq + 1) break;
    const key = chatKeyOf(msg);
    if (key && !viewing(key)) break;
    seq = msg.seq;
  }
  await raiseSeq(seq);
}

async function announce(messages) {
  try { chimeFor(messages); } catch (err) { /* sound is optional */ }
  const latest = new Map();
  for (const msg of messages) {
    const key = chatKeyOf(msg);
    if (!key) continue;
    if (key === "lobby" && !(state.lobby && state.lobby.joined)) continue;
    if (viewing(key)) continue;
    unreadBy.set(key, (unreadBy.get(key) || 0) + 1);
    if (msg.id) { if (!unreadIds.has(key)) unreadIds.set(key, new Set()); unreadIds.get(key).add(msg.id); }
    if (chatIsMuted(key)) continue;   // 0.23.2: muted chat, unread only
    latest.set(key, msg);
  }
  paintTitle();
  try {
  const choice = muteChoice();
  if (choice.mode !== "on") {
    await raiseSeq(lastSeq);
    return;
  }
  if (pushReady) {
    await advanceSeen(messages);
    return;
  }
  const alerts = "Notification" in window && Notification.permission === "granted";
  if (alerts) {
    for (const [key, msg] of latest) {
      const many = key === "lobby" || key.indexOf("g:") === 0;
      const title = key === "lobby" ? "Lobby" : key.indexOf("g:") === 0 ? groupName(key.slice(2)) : msg.sender;
      let body = many ? (msg.sender || "Someone") + " sent a message" : "New message";
      try {
        const opened = await openMessage(msg);
        if (opened && opened.payload) {
          const text = previewOf(opened.payload, msg);
          body = many ? (msg.sender || "Someone") + ": " + text : text;
        }
      } catch (err) { /* the alert still names the sender */ }
      let note;
      let icon = document.querySelector('link[rel="icon"][data-org]')?.getAttribute("href") || "/favicon.png";  // beta.13: org picture on branded servers
      try {
        const r = await fetch(avatarUrl(msg.sender || ""), {credentials: "same-origin"});
        if (r.ok) icon = URL.createObjectURL(await r.blob());
      } catch (err) { /* keep the site icon */ }
      try {
        note = new Notification(title, {body: body, icon: icon, badge: "/favicon.png", tag: "branch-" + key});
      } catch (err) {
        continue;
      }
      note.onclick = () => {
        window.focus();
        const target = roomFromKey(key);
        if (target) selectRoom(target);
        note.close();
      };
    }
  }
  await raiseSeq(lastSeq);
  } catch (err) { /* the unread count still shows */ }
}

let muteTimer = 0;
let notifyAsked = false;

function muteChoice() {
  const raw = localStorage.getItem("huzz-chat-mute") || "";
  if (raw === "until") return {mode: "until"};
  const match = /^(\d+):(\d+)$/.exec(raw);
  if (match) {
    const until = Number(match[2]);
    if (until > Date.now()) return {mode: match[1], until};
    localStorage.removeItem("huzz-chat-mute");
  } else if (raw) {
    localStorage.removeItem("huzz-chat-mute");
  }
  return {mode: "on"};
}

// 26.10.10b: the Android app's own notifier honours the in-app mute too. Feature-detected; older apps and
// browsers simply don't have it.
function pushNativeMute() {
  try {
    const n = window.BranchChatNative;
    if (!n || typeof n.setNotifyMute !== "function") return;
    const c = muteChoice();
    n.setNotifyMute(c.mode === "until" ? -1 : (c.until || 0));
  } catch (err) { /* older app */ }
}
function nativeNotifyBlocked() {
  try {
    const n = window.BranchChatNative;
    return !!(n && typeof n.notifyEnabled === "function" && n.notifyEnabled() === false);
  } catch (err) { return false; }
}
document.addEventListener("visibilitychange", () => { if (!document.hidden && window.BranchChatNative) { pushNativeMute(); try { paintNotify(); } catch (err) { /* not ready */ } } });

function scheduleUnmute() {
  if (muteTimer) clearTimeout(muteTimer);
  muteTimer = 0;
  const choice = muteChoice();
  if (!choice.until) return;
  const wait = Math.max(0, Math.min(choice.until - Date.now(), 2147483647));
  muteTimer = setTimeout(() => {
    localStorage.removeItem("huzz-chat-mute");
    idbSet("notify-mute", "").catch(() => {});
    pushNativeMute();
    paintNotify();
    syncPush();
  }, wait);
}

function setMute(value) {
  if (value === "until") {
    localStorage.setItem("huzz-chat-mute", "until");
  } else if (value === "30" || value === "45" || value === "60") {
    localStorage.setItem("huzz-chat-mute", value + ":" + (Date.now() + Number(value) * 60 * 1000));
  } else {
    localStorage.removeItem("huzz-chat-mute");
  }
  idbSet("notify-mute", localStorage.getItem("huzz-chat-mute") || "").catch(() => {});
  pushNativeMute();
  scheduleUnmute();
  paintNotify();
  syncPush();
}

// 26.10.10: desktop app only. The Start at login switch talks to the app through window.bcDesktopApp (preload.js);
// without the bridge (browser, phone, older desktop app) the row stays hidden.
async function setupDesktopAutostart() {
  try {
    const bridge = window.bcDesktopApp;
    const row = $("desktop-autostart-row"), box = $("desktop-autostart");
    if (!bridge || typeof bridge.getStartAtLogin !== "function" || !row || !box) return;
    const st = await bridge.getStartAtLogin();
    if (!st || !st.supported) return;
    box.checked = !!st.on;
    row.hidden = false;
    box.addEventListener("change", async () => {
      try { box.checked = !!(await bridge.setStartAtLogin(box.checked)); } catch (err) { /* keep what the user sees */ }
    });
    if (typeof bridge.onStartAtLoginChange === "function") bridge.onStartAtLoginChange((on) => { box.checked = !!on; });
  } catch (err) { /* hidden */ }
}
async function setupDesktopClose() {
  try {
    const bridge = window.bcDesktopApp;
    const row = $("desktop-close-row"), sel = $("desktop-close");
    if (!bridge || typeof bridge.getCloseAction !== "function" || !row || !sel) return;
    const st = await bridge.getCloseAction();
    if (!st || !st.supported) return;
    sel.value = st.action;
    row.hidden = false;
    sel.addEventListener("change", async () => {
      try { sel.value = await bridge.setCloseAction(sel.value); } catch (err) { /* keep it */ }
    });
    if (typeof bridge.onCloseActionChange === "function") bridge.onCloseActionChange((a) => { sel.value = a; });
  } catch (err) { /* hidden */ }
}

// 26.10.10c: "Check for updates" in the installed apps, in place of Add to Home Screen. Uses the app's own updater
// (only Latest releases, same verified download/install flow). Feature-detected: the bridge must offer
// checkForUpdates() -> {current, latest, available} (or a Promise of it) and applyUpdate(); otherwise nothing changes.
function updateBridge() {
  const cands = [window.bcDesktopApp, window.BranchChatNative];
  for (const b of cands) if (b && typeof b.checkForUpdates === "function" && typeof b.applyUpdate === "function") return b;
  return null;
}
function setupUpdateRow() {
  try {
    const bridge = updateBridge();
    const btn = $("menu-update");
    if (!bridge || !btn || btn.dataset.ready) return;
    btn.dataset.ready = "1";
    document.documentElement.classList.add("bc-has-updater");
    btn.hidden = false;
    let pending = null, busy = false;
    const vtag = (v) => "v" + String(v || "").replace(/^v/, "");
    btn.addEventListener("click", async () => {
      if (busy) return;
      if (pending) {
        try { await bridge.applyUpdate(); } catch (err) { btn.textContent = "Update failed, try again"; pending = null; }
        return;
      }
      busy = true;
      btn.textContent = "Checking\u2026";
      try {
        const r = await bridge.checkForUpdates();
        if (r && r.available && r.latest) { pending = r.latest; btn.textContent = "Update to " + vtag(r.latest); }
        else if (r && !r.error) btn.textContent = "Up to date" + (r.current ? " (" + vtag(r.current) + ")" : "");
        else btn.textContent = "Couldn\u2019t check, try again";
      } catch (err) { btn.textContent = "Couldn\u2019t check, try again"; }
      busy = false;
    });
  } catch (err) { /* keep Add to Home Screen */ }
}
// 26.10.10d: "Switch server" in the installed apps. Feature-detected: the bridge (desktop bcDesktopApp or the Android
// BranchChatNative) offers listServers() -> [{url, name, host, current}] (array, JSON string, or a Promise of either) and
// openServer(url) for a SAVED server. Optional: addServer() / manageServers() / removeServer(url). Nothing is hard-coded:
// the list is whatever servers this device has saved, any number of them. Each server keeps its own login (cookies are per
// server), so switching back needs no sign-in.
function serverBridge() {
  for (const b of [window.bcDesktopApp, window.BranchChatNative]) if (b && typeof b.listServers === "function" && typeof b.openServer === "function") return b;
  return null;
}
async function readServers(bridge) {
  let r = await bridge.listServers();
  if (typeof r === "string") { try { r = JSON.parse(r); } catch (err) { r = []; } }
  return Array.isArray(r) ? r.filter((s) => s && typeof s.url === "string") : [];
}
// The front door can't be removed (the apps refuse it), so don't offer Remove for it. Its host comes from the
// bridge when it says (s.frontDoor, bridge.frontDoor/defaultServer); otherwise the installed apps' built-in default.
const APP_FRONT_DOOR_DEFAULT = "https://branchchat.app/";
