    new MutationObserver(() => { if (!panel.hidden) render(); }).observe(panel, {attributes: true, attributeFilter: ["hidden"]});
    const menuEl = $("app-menu");
    if (menuEl) new MutationObserver(() => { if (!menuEl.hidden) render(); }).observe(menuEl, {attributes: true, attributeFilter: ["hidden"]});
    render();
