      c.globalAlpha = k * 0.7; c.drawImage(fxGlow("#ff9a30"), ox - R * 1.6, oy - 5, R * 3.2, 10); // anamorphic streak
      c.drawImage(fxGlow("#ffffff"), ox - 4, oy - R * 0.9, 8, R * 1.8);
