const TREANT_GROW_EXTRA = 1200;  // v2 (Oct 2026): extra ms for the roots growing up to the message (1.2 s -> 2.4 s), so the grab reads
// roots, squeeze and sink; the gap folds over the last quarter (was 2680). The extra is 4/3 of the growth extra so the
// fold (which starts at 75% of this) still begins just as the message is pulled under, not before.
const TREANT_DUR = 2680 + Math.round(TREANT_GROW_EXTRA * 4 / 3);
