  const B = bub.getBoundingClientRect(), G0 = gap.getBoundingClientRect();
  if (!B.width || !B.height) return;
  const id = "trr" + (++trSeq);
  const padX = 38, padT = 38, padB = 34;
  const W = Math.ceil(B.width + padX * 2), H = Math.ceil(B.height + padT + padB);
  const x0 = padX, y0 = padT, x1 = padX + B.width, y1 = padT + B.height, gy = y1 + 3, yc = gy + 3;
