  const rrect = (attrs) => '<rect x="' + x0.toFixed(1) + '" y="' + y0.toFixed(1) + '" width="' + bw.toFixed(1) + '" height="' + bh.toFixed(1) + '" rx="' + rad + '" ' + attrs + '/>';
  const lump = Array.from({length: 24}, () => Math.random());
