      const e = document.createElementNS(NS, "ellipse");
      const r = 1 + Math.random() * (R.thin ? 1.2 : 2);
      e.setAttribute("rx", (r * 1.2).toFixed(1)); e.setAttribute("ry", r.toFixed(1));
      e.setAttribute("fill", "url(#" + id + "clod)"); e.setAttribute("opacity", "0");
