// apply a pose to the SVG elements (els = cached nodes)
function fmApply(els, P) {
  const set = (n, k, v) => n && n.setAttribute(k, v);
  const lean = P.lean, sh = (p) => { const r = fmRot(p, FM_HIP, lean); return { x: r.x, y: r.y - P.hop }; };
  set(els.torso, "transform", "translate(0 " + fmF(-P.hop) + ") rotate(" + fmF(lean) + " " + FM_HIP.x + " " + FM_HIP.y + ")");
  set(els.head, "transform", "rotate(" + fmF(P.head) + " " + FM_NECK.x + " " + FM_NECK.y + ")");
  set(els.mouth, "d", fmFace(P));
  const bl = Math.max(0.08, P.blink) * (1 - P.happy);
  set(els.eyes, "transform", "translate(0 " + fmF(-41.7 * (1 - bl)) + ") scale(1 " + fmF(bl) + ")");
  set(els.pupils, "transform", "translate(" + fmF(P.lookX * 0.45) + " " + fmF(P.lookY * 0.4) + ")");
  set(els.happy, "opacity", fmF(P.happy));
  set(els.brows, "transform", "translate(0 " + fmF(-P.brow * 0.7) + ") rotate(" + fmF(P.brow < 0 ? P.brow * 6 : P.brow * -2) + " 1 -43.6)");
  const arm = (S, H, bend, o, f) => { const E = fmIK(S, H, 10.6, 10.4); const c = { x: 2 * E.x - (S.x + H.x) / 2, y: 2 * E.y - (S.y + H.y) / 2 };
    const d = "M" + fmF(S.x) + " " + fmF(S.y) + "Q" + fmF(c.x) + " " + fmF(c.y) + " " + fmF(H.x) + " " + fmF(H.y); set(o, "d", d); set(f, "d", d); return d; };
  arm(sh(FM_SF), P.hf, 1, els.armFo, els.armFf);
  arm(sh(FM_SN), P.hn, 1, els.armNo, els.armNf);
  set(els.handF, "transform", "translate(" + fmF(P.hf.x) + " " + fmF(P.hf.y) + ")");
  set(els.handN, "transform", "translate(" + fmF(P.hn.x) + " " + fmF(P.hn.y) + ")");
  // outboard: prop blades squash and flip to read as spinning; the cowling buzzes a little with the throttle
  if (P.spinP !== undefined) {
    set(els.prop, "transform", "translate(-47.4 3.4) scale(1 " + fmF(Math.cos(fmR(P.spinP * 10))) + ")");
    set(els.cowl, "transform", "translate(" + fmF(0.12 * P.thr * Math.sin(P.spinP * 1.7)) + " " + fmF(0.18 * P.thr * Math.sin(P.spinP * 2.3)) + ")");
  }
  const R = P.rod, rd = "M" + fmF(R.g2.x) + " " + fmF(R.g2.y) + "Q" + fmF(R.c.x) + " " + fmF(R.c.y) + " " + fmF(R.tip.x) + " " + fmF(R.tip.y);
  set(els.rod, "d", rd);
  const tq = { x: (R.c.x + R.tip.x) / 2 * 0.2 + R.tip.x * 0.8, y: (R.c.y + R.tip.y) / 2 * 0.2 + R.tip.y * 0.8 };
  set(els.rodTip, "d", "M" + fmF(tq.x) + " " + fmF(tq.y) + "L" + fmF(R.tip.x) + " " + fmF(R.tip.y));
  const cd = "M" + fmF(R.butt.x) + " " + fmF(R.butt.y) + "L" + fmF(R.g2.x) + " " + fmF(R.g2.y); set(els.cork, "d", cd); set(els.cork2, "d", cd);
  const grip = { x: R.butt.x + R.u.x * 4, y: R.butt.y + R.u.y * 4 };
  set(els.reel, "transform", "translate(" + fmF(grip.x) + " " + fmF(grip.y) + ") rotate(" + fmF(P.rodAng) + ")");
  set(els.crank, "transform", "rotate(" + fmF(P.spin) + " 2 2.2)");
}
