/* tdPose(svg, P): apply one pose. P fields (all optional, defaults = the resting grump):
   sx, sy (squash, pivot at the feet), lean (deg), lift (units, whole body up), head: tilt (deg), hx, hy,
   m (mouth open 0..1), f (brow furrow 0..1), lx, ly (look -1..1), sq (lower-lid squint 0..1),
   aL, aR (arm angles, deg: 0 = straight down, 90 = straight out, 180 = straight up), tail (deg), crest (deg),
   fL, fR (foot lift units), puff (chest/belly breath scale). Every value is continuous, so any in-between pose is valid. */
function tdPose(svg, P) {
  const q = (s) => svg.querySelector(s), set = (s, a, v) => { const n = svg.__td[s] || (svg.__td[s] = q(s)); if (n) n.setAttribute(a, v); };
  if (!svg.__td) svg.__td = {};
  const g = (k, d) => (P[k] === undefined ? d : P[k]);
  const sx = g("sx", 1), sy = g("sy", 1), lean = g("lean", 0), lift = g("lift", 0), puff = g("puff", 1);
  set(".td-root", "transform", "translate(40 63) rotate(" + F2(lean) + ") translate(0 " + F2(-lift) + ") scale(" + F3(sx * (1 + (puff - 1) * .5)) + " " + F3(sy * puff) + ") translate(-40 -63)");
  const sh = Math.max(.35, 1 - lift / 30);
  set(".td-shadow", "transform", "translate(40 62.8) scale(" + F3(sh * sx) + " 1) translate(-40 -62.8)");
  set(".td-shadow", "opacity", F3(.28 * sh));
  set(".td-tail", "transform", "rotate(" + F2(g("tail", 0)) + " 56 56.4)");
  set(".td-footL", "transform", "translate(0 " + F2(-g("fL", 0)) + ")");
  set(".td-footR", "transform", "translate(0 " + F2(-g("fR", 0)) + ")");
  set(".td-armLw", "transform", "translate(26.4 39) rotate(" + F2(g("aL", 24)) + ")");
  set(".td-armRw", "transform", "translate(53.6 39) rotate(" + F2(-g("aR", 24)) + ")");
  set(".td-head", "transform", "translate(" + F2(40 + g("hx", 0)) + " " + F2(34 + g("hy", 0)) + ") rotate(" + F2(g("tilt", 0)) + ") translate(-40 -34)");
  set(".td-crest", "transform", "rotate(" + F2(g("crest", 0)) + " 40 14)");
  // mouth: one "open" value drives the hole, chin, teeth, tongue and the closed-mouth fangs
  const m = Math.max(0, Math.min(1.15, g("m", 0))), f = g("f", .35);
  const Lx = 33.4 - 2.6 * m, Rx = 46.6 + 2.6 * m, cy = 31.4 - .3 * m, uy = 29.2 - 2.2 * m, ly = 30 + 15 * m;
  const P2 = (x, y) => F2(x) + " " + F2(y);
  const mouth = "M" + P2(Lx, cy) + "Q" + P2(40, uy) + " " + P2(Rx, cy) + "Q" + P2(40, ly) + " " + P2(Lx, cy) + "Z";
  set(".td-mouth", "d", mouth); set(".td-mclip", "d", mouth); set(".td-mline", "d", mouth);
  // chin bulges down with the jaw
  const cb = cy + 1 + 6.4 * m;
  set(".td-chin", "d", "M" + P2(Lx - 1.2, cy - .3) + "C" + P2(Lx - .6, cb + 1.6) + " " + P2(Rx + .6, cb + 1.6) + " " + P2(Rx + 1.2, cy - .3) + "Q" + P2(40, cy + .2 + 2 * m) + " " + P2(Lx - 1.2, cy - .3) + "Z");
  set(".td-jaw", "transform", "translate(0 " + F2(4.2 * m) + ")");
  const qb = (t, a, c, b) => (1 - t) * (1 - t) * a + 2 * (1 - t) * t * c + t * t * b;
  const teeth = (yc, dirn, n, fangAt, len, fang) => {
    let d = "";
    for (let i = 0; i < n; i++) {
      const t0 = .1 + .8 * i / n, t1 = .1 + .8 * (i + 1) / n, tm = (t0 + t1) / 2;
      const x0 = qb(t0, Lx, 40, Rx), y0 = qb(t0, cy, yc, cy), x1 = qb(t1, Lx, 40, Rx), y1 = qb(t1, cy, yc, cy), xm = qb(tm, Lx, 40, Rx), ym = qb(tm, cy, yc, cy);
      const big = fangAt.some((fa) => Math.abs(fa - tm) < .06), L = big ? fang : len;
      d += "M" + P2(x0, y0 - dirn * .6) + "L" + P2(xm, ym + dirn * L) + "L" + P2(x1, y1 - dirn * .6) + "Z";
    }
    return d;
  };
  set(".td-teethU", "d", teeth(uy, 1, 9, [.19, .81], 1.3 + .35 * m, 3 + .7 * m));
  set(".td-teethL", "d", teeth(ly, -1, 7, [.27, .73], 1.1 + .25 * m, 2.3 + .6 * m));
  set(".td-mglow", "opacity", F3(g("glow", 0))); set(".td-mglow", "cy", F2((uy + ly) / 2 - 1));
  set(".td-tongue", "cy", F2(qb(.5, cy, ly, cy) - 1.3)); set(".td-tongue", "rx", F2(3 + 2.2 * m));
  // two little underbite fangs poke up over the lip while the mouth is shut; they fade as the jaw opens
  const fo = Math.max(0, 1 - m * 4);
  set(".td-fangs", "d", fo > 0 ? "M" + P2(35.6, 31.2) + "L" + P2(36.3, 28.9) + "L" + P2(37.1, 31) + "ZM" + P2(42.9, 31) + "L" + P2(43.7, 28.9) + "L" + P2(44.4, 31.2) + "Z" : "");
  set(".td-fangs", "opacity", F3(fo));
  // eyes: look, scowl lid (more with furrow, never past the pupil top), squint
  const lx = g("lx", 0) * 1.15, lyy = g("ly", 0) * 1.05;
  set(".td-irisL", "transform", "translate(" + F2(lx) + " " + F2(lyy) + ")");
  set(".td-irisR", "transform", "translate(" + F2(lx) + " " + F2(lyy) + ")");
  const lid = (cx, s) => { // s = +1 left eye (inner side is +x), -1 right eye
    const inner = 15.9 + 1.5 * f, outer = 14.4 + .5 * f; // lid edge heights: inner side lower = grumpy
    const xi = cx + s * 4.2, xo = cx - s * 4.2;
    return "M" + P2(xo, 13) + "L" + P2(xo, outer) + "Q" + P2(cx, (inner + outer) / 2 + .5) + " " + P2(xi, inner) + "L" + P2(xi, 13) + "Z";
  };
  set(".td-lidL", "d", lid(34, 1)); set(".td-lidR", "d", lid(46, -1));
  const sq = g("sq", 0), lo = 23.8 - 2.2 * sq;
  const low = (cx) => "M" + P2(cx - 4.2, 24.2) + "L" + P2(cx - 4.2, 23.2) + "Q" + P2(cx, lo - .6) + " " + P2(cx + 4.2, 23.2) + "L" + P2(cx + 4.2, 24.2) + "Z";
  set(".td-lowL", "d", low(34)); set(".td-lowR", "d", low(46));
  // brows: pivot at the inner end; furrow pulls the inner ends down and in and steepens them
  const br = 7 * f - 2, bd = 1.1 * f - .3, bi = .7 * f;
  set(".td-browL", "transform", "translate(" + F2(bi) + " " + F2(bd) + ") rotate(" + F2(br) + " 38.6 16.6)");
  set(".td-browR", "transform", "translate(" + F2(-bi) + " " + F2(bd) + ") rotate(" + F2(-br) + " 41.4 16.6)");
}
const F2 = (v) => (+v).toFixed(2), F3 = (v) => (+v).toFixed(3);
