/* cr-art.js (new-snaps): art for the Origami Crane delete animation (key "crane").
   Two pieces:
   - CRANE_SVG: what sits in the shared stage (80x64 art box, like every character): a little folded-paper window on a
     sill, with two paper shutters and a starry night sky behind them, plus a paper crane perched beside it. That full
     picture is the REST pose, so the same string is the menu preview and the picker icon (static/snap/crane.svg). In the
     animation the perched crane is hidden (the flying crane is a separate element, see cr-char.js) and the window pops
     open, takes the crane in, closes, and folds away.
   - crBirdSVG(front, back, edge): the flying crane on its own (100x70 box, facing right), drawn as flat origami facets.
     Its wings, neck and tail paths are re-shaped every frame by crBirdPose(); colours come from the message's own colour.
   No text in the art (the stage can be mirrored). Hooks: .cr-win .cr-shL .cr-shR .cr-hole .cr-glow .cr-perch */
const CR_PAPER = {front: "#9fd6b0", back: "#eef8ef", edge: "#4f8a62"};   // default paper (green, for the still)
// The crane's facets for a pose: k = 0 folded flat (neck and tail tucked, wings closed), 1 fully pulled out;
// wing = wing-tip height (-1 = straight up, 0 = level, 1 = straight down). Returns path data strings.
function crBirdPose(k, wing) {
  const L = (a, b, u) => a + (b - a) * u, P = (x, y) => x.toFixed(2) + " " + y.toFixed(2);
  const neckX = L(60, 84, k), neckY = L(36, 14, k), tailX = L(36, 10, k), tailY = L(36, 18, k);
  const tipY = 38 + wing * 34, tipX = 46 - 6 * Math.abs(wing);
  const wingN = "M" + P(40, 38) + "L" + P(56, 38) + "L" + P(tipX, tipY) + "Z";
  const wingNa = "M" + P(48, 38) + "L" + P(56, 38) + "L" + P(tipX, tipY) + "Z";   // one half of the wing, for the fold shading
  const wingF = "M" + P(44, 36) + "L" + P(58, 36) + "L" + P(tipX + 6, 36 + wing * 30) + "Z";
  return {
    body: "M" + P(30, 40) + "L" + P(48, 32) + "L" + P(66, 40) + "L" + P(48, 47) + "Z",
    bodyHi: "M" + P(30, 40) + "L" + P(48, 32) + "L" + P(48, 47) + "Z",
    neck: "M" + P(60, 39) + "L" + P(65, 40) + "L" + P(neckX, neckY) + "Z",
    head: "M" + P(neckX, neckY) + "L" + P(neckX + L(2, 7, k), neckY + L(1, 4, k)) + "L" + P(neckX + .5, neckY + 2.5) + "Z",
    tail: "M" + P(34, 39) + "L" + P(39, 38.5) + "L" + P(tailX, tailY) + "Z",
    wingN, wingNa, wingF, down: wing > 0,
  };
}
function crBirdSVG(front, back, edge) {
  const p = crBirdPose(1, -.55);
  return '<svg viewBox="0 0 100 70" aria-hidden="true" focusable="false">' +   // no style attribute: the page's CSP blocks inline styles (cr.css sets overflow)
    '<path class="crb-wingF" d="' + p.wingF + '" fill="' + edge + '" opacity=".55"/>' +
    '<path class="crb-tail" d="' + p.tail + '" fill="' + front + '" stroke="' + edge + '" stroke-width=".5" stroke-linejoin="round"/>' +
    '<path class="crb-neck" d="' + p.neck + '" fill="' + front + '" stroke="' + edge + '" stroke-width=".5" stroke-linejoin="round"/>' +
    '<path class="crb-head" d="' + p.head + '" fill="' + back + '" stroke="' + edge + '" stroke-width=".45" stroke-linejoin="round"/>' +
    '<path class="crb-body" d="' + p.body + '" fill="' + front + '" stroke="' + edge + '" stroke-width=".55" stroke-linejoin="round"/>' +
    '<path class="crb-bodyHi" d="' + p.bodyHi + '" fill="#fff" opacity=".28"/>' +
    '<path d="M48 32L48 47" stroke="' + edge + '" stroke-width=".4" opacity=".6"/>' +
    '<path class="crb-wingN" d="' + p.wingN + '" fill="' + back + '" stroke="' + edge + '" stroke-width=".55" stroke-linejoin="round"/>' +
    '<path class="crb-wingNa" d="' + p.wingNa + '" fill="#000" opacity=".08"/>' +
    '</svg>';
}
// the resting crane for the still: same facets, sitting on the ground to the right of the window (paper cranes have no legs)
function crPerch() {
  const p = crBirdPose(1, -.85), c = CR_PAPER;
  return '<g class="cr-perch" transform="translate(31 37.2) scale(.55)">' +
    '<path d="' + p.wingF + '" fill="' + c.edge + '" opacity=".55"/>' +
    '<path d="' + p.tail + '" fill="' + c.front + '" stroke="' + c.edge + '" stroke-width=".7"/>' +
    '<path d="' + p.neck + '" fill="' + c.front + '" stroke="' + c.edge + '" stroke-width=".7"/>' +
    '<path d="' + p.head + '" fill="' + c.back + '" stroke="' + c.edge + '" stroke-width=".6"/>' +
    '<path d="' + p.body + '" fill="' + c.front + '" stroke="' + c.edge + '" stroke-width=".7"/>' +
    '<path d="' + p.bodyHi + '" fill="#fff" opacity=".28"/>' +
    '<path d="' + p.wingN + '" fill="' + c.back + '" stroke="' + c.edge + '" stroke-width=".7"/>' +
    '<path d="' + p.wingNa + '" fill="#000" opacity=".08"/></g>';
}
