    setTimeout(() => { fig.classList.add("tr-shake"); playRustle(); }, 680);
    // v2: while the roots grow (now slower) he shakes his canopy a second time to urge them on
    setTimeout(() => { fig.classList.remove("tr-shake"); void fig.offsetWidth; fig.classList.add("tr-shake"); playRustle(); }, TREANT_PRE + 700);
    setTimeout(() => { fig.classList.add("tr-nod"); playGiggle(0.84); }, TREANT_PRE + 1380 + TREANT_GROW_EXTRA);
    setTimeout(() => fig.classList.add("snap-out"), TREANT_PRE + 2080 + TREANT_GROW_EXTRA);
