  const target = bub && bub.isConnected ? bub.getBoundingClientRect() : null;
  const hasMsg = !!(target && target.width > 0 && target.height > 0 && target.bottom > 0 && target.top < comp.top);
  const col = hasMsg ? bnColour(bub) : "rgb(214,226,206)";
