  const dust = (x, y, n, stride) => { for (let i = 0; i < Math.ceil(n / stride); i++) parts.push({x: x + (rnd() - .5) * 20, y, vx: (rnd() - .5) * 60, vy: -15 - rnd() * 25, s: 2.5 + rnd() * 3, age: 0, life: .5 + rnd() * .3, col: "#b9a184", rot: 0, spin: 0, dust: true}); };
