    setT(G.beaver, "translate(50 62) scale(" + fsx.toFixed(3) + " 1) scale(" + (1 + .06 * land).toFixed(3) + " " + (1 - .07 * land + .04 * hop).toFixed(3) + ") rotate(" + (3 * wad).toFixed(2) + ") translate(-50 -62)");
    G.occ.setAttribute("transform", "translate(" + x.toFixed(2) + " 0)");
