    const lookUp = bvSS(bvU(t, BV.IN1 - 100, BV.GRAB)) * (1 - bvSS(bvU(t, BV.GRAB + 150, BV.LOG)));
    const chew = bvU(t, BV.LOG, BV.LOG + 60) * (1 - bvU(t, BV.CHEW1 - 60, BV.CHEW1)), chat = chew * (.5 + .5 * Math.sin((t - BV.LOG) / 1000 * 2 * Math.PI * 11));
