    const reach = bvBell(t, BV.GRAB - 250, BV.GRAB + 250), holdA = bvSS(bvU(t, BV.GRAB + 100, BV.LOG)) * (1 - bvSS(bvU(t, BV.CHEW1 - 50, BV.CHEW1 + 100)));
