// Start the delete animation for one message if it is on screen.
function snapRow(id, how) {
  if (snapping.has(id)) return;
  const log = $("log");
  const row = log && log.querySelector('.msg[data-id="' + CSS.escape(id) + '"]');
  if (!row) return;
  row.classList.add("snapping");
  const info = snapElement(row, how);
  snapping.set(id, info);
  setTimeout(() => {
    snapping.delete(id);
    info.gap.remove();
  }, info.pre + info.dur + 80);
}

// The gap element holding a message that is mid-animation (re-used on every redraw).
function snapGap(id) {
  // The exact same gap node (holding the real deleted row) is put back on every re-render.
  return snapping.get(id).gap;
}

// #snapdemo links: play a delete animation on a sample message, for showing the characters.
function snapDemo() {
  const m = /^#snapdemo(?:[-_=]?([a-z]+))?\/?$/i.exec(decodeURIComponent(location.hash || ""));
  if (m && m[1]) m[1] = m[1].toLowerCase();
  if (m && m[1] && !SNAP_CHARS.includes(m[1])) m[1] = "";
  if (!m) return;
  history.replaceState(null, "", location.pathname + location.search);
  let tries = 0;
  const ready = () => {
    const log = $("log");
    if (!(state.me && state.me.username) || !log) {
      if (++tries < 80) setTimeout(ready, 250);
      return;
    }
    const row = document.createElement("div");
    row.className = "msg mine";
    const bubble = document.createElement("div");
    bubble.className = "bubble";
    bubble.textContent = "This message will self-destruct";
    row.append(bubble);
    log.append(row);
    log.scrollTop = log.scrollHeight;
    const run = () => {
      if (!row.isConnected) return;
      snapForce = m[1] || "";
      snapMarkOwn();   // a preview this person asked for counts as their own delete (voice on)
      const info = snapElement(row);
      snapForce = "";
      setTimeout(() => info.gap.remove(), info.pre + info.dur + 80);
    };
    const ctx = snapCtx();
    const go = () => setTimeout(run, 1000);
    if (ctx && ctx.state === "suspended") {
      ctx.resume().catch(() => {}).finally(() => {
        if (ctx.state === "running") { go(); return; }
        const chip = document.createElement("button");
        chip.type = "button";
        chip.className = "snap-chip";
        chip.textContent = "Tap to watch the delete animation";
        chip.addEventListener("click", () => {
          chip.remove();
          ctx.resume().catch(() => {}).finally(go);
        });
        document.body.append(chip);
      });
    } else {
      go();
    }
  };
  setTimeout(ready, 600);
}
snapDemo();

(() => {
  const box = document.getElementById("snapchar-choices");
  if (!box) return;
  // 26.10.2: shows and saves the signed-in account's own pick (see snapPick above), not a browser-wide one.
  const paint = () => {
    const cur = snapPick();
    for (const b of box.querySelectorAll("button")) b.setAttribute("aria-pressed", String(b.dataset.snapchar === cur));
  };
  window.bcSnapPaint = paint;
  box.addEventListener("click", (ev) => {
    const b = ev.target instanceof Element && ev.target.closest("button[data-snapchar]");
    if (!b) return;
    snapSave(b.dataset.snapchar, true);
    paint();
  });
  paint();
})();

