function paintAccount() {
  const on = !!(state.me && state.me.totp);
  const status = $("totp-status");
  if (!status) return;
  status.textContent = on
    ? "On. Sign-in asks for an authenticator code after the password."
    : "Off. Sign-in uses your password only.";
  if (on) totpSetup = false;
  $("totp-off").hidden = on || totpSetup;
  $("totp-on").hidden = !on;
  $("totp-setup").hidden = on || !totpSetup;
}

function render() {
  paintAccount();
  renderPeople();
  renderThreadHead();
  const joined = state.lobby && state.lobby.joined;
  const blocked = (room.box === "lobby" && !joined) || (room.box === "group" && !groupById(room.gid));
  $("text").disabled = blocked;
  $("send").disabled = blocked;
  if (shareWaiting && !shareChoosing && !blocked && room.box !== "none") setTimeout(fillShare, 0);
  $("emoji-btn").disabled = blocked;
  $("gif-btn").disabled = blocked;   // 26.10.3
  emojiUseLoad();                    // 26.10.3: load this account's emoji habits once it is known (cheap otherwise)
  $("file-btn").disabled = blocked;
  if (blocked) {
    closePicker();
    closeAttach();
    closeReact();
  }
  renderLog();
  showAttach();
}

