  if (h > bgTall) {
    bgTall = h;
    document.documentElement.style.setProperty("--app-tall", bgTall + "px");
  }
  const layer = $("chat-bg");
  if (!layer || layer.hidden) return;
  const top = layer.getBoundingClientRect().top;
  const want = Math.round(Math.max(layer.clientHeight, bgTall - top));
