const BGA_SCENES = {pines: "pines", ember: "ember",   // preset id -> scene script in static/bganim/ (Ember added Oct 19 2026: rising campfire embers, breathing glow)
  dusk: "dusk", mist: "mist", meadow: "meadow", tide: "tide", linen: "linen", night: "night",   // 26.10.4: the six built Oct 18 but never switched on
  "fourth-july": "fourth-july"};   // 26.10.4 fix: fireworks, flickering sparklers, twinkling stars (the switch used to do nothing on it)
