/* ---- 0.23.2: per-chat mute (Off, 1 hour, 8 hours, 1 week, until I turn it back on). Saved on the server for this
   account, so every device and the phone push follow it. The control sits in the chat header (bell) for now, and
   right-click / long-press on a chat in the list; it moves into the chat settings pop-up later. ---- */
let muteFor = "";
let longPressAt = 0;
function rowTapOk() { const cs = document.getElementById("chat-sheet"); return Date.now() - longPressAt > 900 && !$("mute-dialog").open && !(cs && cs.open) && Date.now() - (window.chatDragEndedAt || 0) > 400; }
function muteTitle(key) {
  if (key === "lobby") return "Lobby";
  if (key.indexOf("g:") === 0) return groupName(key.slice(2));
  const peer = key.slice(3);
  return dn(peer) || peer;
}
function muteUntilText(until) {
  const d = new Date(until * 1000);
  const sameDay = d.toDateString() === new Date().toDateString();
  const time = d.toLocaleTimeString([], {hour: "numeric", minute: "2-digit"});
  return sameDay ? time : d.toLocaleDateString([], {weekday: "short", month: "short", day: "numeric"}) + ", " + time;
}
function muteStatusText(key) {
  const until = chatMuteUntil(key);
  if (until === null) return "Not muted. Sounds and alerts are on for this chat.";
  if (until === 0) return "Muted until you turn it back on.";
  return "Muted until " + muteUntilText(until) + ".";
}
function paintMuteDialog() {
  const until = chatMuteUntil(muteFor);
  // A timed mute shows the closest choice for the time left (1 hour, 8 hours or 1 week); the line below gives the exact end.
  const left = until ? until - Date.now() / 1000 : 0;
  const pick = until === null ? "off" : until === 0 ? "forever" : left <= 3600 + 60 ? "1h" : left <= 8 * 3600 + 60 ? "8h" : "1w";
  document.querySelectorAll('#mute-opts input[name="mute-for"]').forEach((r) => { r.checked = r.value === pick; });
  $("mute-who").textContent = muteTitle(muteFor);
  $("mute-status").textContent = muteStatusText(muteFor);
}
function openMute(key) {
  if (!roomFromKey(key)) return;
  muteFor = key;
  paintMuteDialog();
  const dlg = $("mute-dialog");
  if (!dlg.open) dlg.showModal();
}
function muteButton(key) {
  const muted = chatIsMuted(key);
  const b = document.createElement("button");
  b.type = "button";
  b.className = "ghost icon mute-btn" + (muted ? " is-muted" : "");
  b.id = "mute-btn";
  b.setAttribute("aria-label", muted ? "Chat muted. Change mute" : "Mute this chat");
  b.title = muted ? "Muted" : "Mute this chat";
  b.innerHTML = muted ? BELL_OFF_SVG.replace(/width="15" height="15"/, 'width="22" height="22"') : BELL_SVG;
  b.addEventListener("click", () => openMute(key));
  return b;
}
document.querySelectorAll('#mute-opts input[name="mute-for"]').forEach((r) => r.addEventListener("change", async () => {
  if (!r.checked || !muteFor) return;
  const key = muteFor;
  $("mute-status").textContent = "Saving…";
  try {
    const data = await post("/api/chats/mute", {chat: key, for: r.value});
    state.mutes = data.mutes || {};
    paintKey = "";
    maybeRender();
    if (muteFor === key) paintMuteDialog();
  } catch (err) {
    $("mute-status").textContent = err.message || "That did not save. Try again.";
  }
}));
function rowMuteKey(target) {
  const row = target instanceof Element && target.closest(".chat-row");
  if (!row) return "";
  if (row.dataset.key) return row.dataset.key;
  return row.id === "lobby-row" ? "lobby" : row.dataset.gid ? "g:" + row.dataset.gid : row.dataset.peer ? "dm:" + row.dataset.peer : "";
}
$("sidebar").addEventListener("contextmenu", (ev) => {
  const key = rowMuteKey(ev.target);
  if (!key) return;
  ev.preventDefault();
  openChatMenu(key);   // chatlist-pin-reorder: Pin / Archive / Mute menu (was: mute choices only)
});
(() => {
  // Long-press (touch) on a chat in the list opens the same mute choices; the tap that ends it does not open the chat.
  let timer = 0, sx = 0, sy = 0, fired = false;
  // (longPressAt, read by rowTapOk(), lets each row ignore the tap that ends a long-press in every engine)
  const side = $("sidebar");
  const stop = () => { if (timer) clearTimeout(timer); timer = 0; };
  side.addEventListener("pointerdown", (ev) => {
    fired = false;
    if (ev.pointerType !== "touch") return;
    if (ev.target instanceof Element && ev.target.closest(".drag-handle")) return;   // the grip drags instead
    const key = rowMuteKey(ev.target);
    if (!key) return;
    sx = ev.clientX; sy = ev.clientY;
    stop();
    timer = setTimeout(() => { timer = 0; fired = true; longPressAt = Date.now(); openChatMenu(key); }, 550);
  });
  side.addEventListener("pointermove", (ev) => { if (timer && Math.hypot(ev.clientX - sx, ev.clientY - sy) > 10) stop(); });
  for (const n of ["pointerup", "pointercancel", "scroll"]) side.addEventListener(n, stop, true);
  side.addEventListener("click", (ev) => { if (fired && rowMuteKey(ev.target)) { ev.preventDefault(); ev.stopPropagation(); fired = false; } }, true);
})();
/* ===== 0.21.01: Telegram-style composer and emoji/GIF panel =====
   One rounded message bar: emoji/GIF button | text | Send, with the round + (attach)
   just outside it on the left. The emoji/GIF button swaps the on-screen keyboard for a
   panel of the same height in the same place, so the messages and the bar stay put.
   Keyboard height: the page is resized by the keyboard (interactive-widget=resizes-content
   in browsers, adjustResize in the Android app), so it is the drop from the tallest
   height seen at this width, plus any part the keyboard covers (visualViewport).
   The last one seen is remembered per orientation; 40% of the screen until then.
   While the keyboard slides away (or back), the panel is sized to "remembered minus
   what the keyboard still takes", so the bar does not move during the swap. */
const picker = {open: false, mode: "", tab: "emoji", query: {emoji: "", gif: "", stickers: ""}, waitTimer: 0};
