function placeProfilePop() {
  const bar = $("me-bar");
  const pop = $("profile-pop");
  if (!bar || !pop) return;
  let rect = bar.getBoundingClientRect();
  if (!rect.width) rect = {left: 8, right: window.innerWidth - 8, top: window.innerHeight};  // dock hidden (phone chat): sheet from the bottom
  const margin = 8;
  const width = Math.min(380, window.innerWidth - margin * 2);
  let left = rect.left;
  if (left + width > window.innerWidth - margin) left = window.innerWidth - width - margin;
  if (left < margin || rect.right < 0) left = margin;
  pop.style.left = left + "px";
  pop.style.width = width + "px";
  const above = rect.top > 80 ? window.innerHeight - rect.top + margin : margin;
  pop.style.bottom = above + "px";
  // Cap below the top banner: the popup grows upward from the dock, so its
  // height must stop at the header's bottom edge, not the top of the screen.
  const head = document.querySelector("header");
  const bar2 = $("thread-head");
  const headBottom = Math.max(0, head ? head.getBoundingClientRect().bottom : 0, bar2 ? bar2.getBoundingClientRect().bottom : 0);
  const view = window.visualViewport;
  const viewTop = view ? view.offsetTop : 0;
  const ceiling = Math.max(headBottom, viewTop) + margin;
  document.documentElement.style.setProperty("--header-h", Math.round(headBottom) + "px");
  const floor = rect.top > 80 ? rect.top - margin : window.innerHeight - margin;
  pop.style.maxHeight = Math.max(160, floor - ceiling) + "px";
  pop.style.top = "auto";
}

