  for (const id of ["pass-current", "pass-new", "pass-again"]) $(id).removeAttribute("aria-invalid");
  const bad = (id, text) => { $("pass-note").textContent = text; $(id).setAttribute("aria-invalid", "true"); $(id).focus(); };
  if (!$("pass-current").value) { bad("pass-current", "Enter your current password."); return; }
  if (next.length < 8) { bad("pass-new", "Password must be at least 8 characters."); return; }
