const SMILEY = "/static/maple-leaf.svg?v=1";
let profileSavedUrl = "";
let profilePendingUrl = "";
let profilePendingBlob = null;

function paintProfile(url) {
  // The corner chip, the menu, and the popup all show this same picture.
  for (const id of ["profile-photo", "profile-scale-a", "profile-scale-b", "profile-scale-c", "menu-photo", "me-photo"]) {
    const img = $(id);
    if (img) img.src = url;
  }
}

function profileNote(text) {
  for (const id of ["profile-note", "menu-profile-note"]) {
    const el = $(id);
    if (el) el.textContent = text;
  }
}

function setProfilePending(show) {
  for (const id of ["profile-actions", "menu-profile-actions"]) {
    const el = $(id);
    if (el) el.hidden = !show;
  }
}

function clearPendingProfile() {
  // Drop a preview that was not applied. The saved picture, or the smiley, stays.
  if (profilePendingUrl) URL.revokeObjectURL(profilePendingUrl);
  profilePendingUrl = "";
  profilePendingBlob = null;
  const input = $("profile-file");
  if (input) input.value = "";
  setProfilePending(false);
}

async function loadProfile() {
  // The picture is account data, not a message. Only this signed-in browser asks for it.
  clearPendingProfile();
  profileNote("");
  let res;
  try {
    res = await fetch("/api/account/avatar", {cache: "no-store"});
  } catch (err) {
    paintProfile(profileSavedUrl || SMILEY);
    return;
  }
  if (!res.ok) {
    if (profileSavedUrl) URL.revokeObjectURL(profileSavedUrl);
    profileSavedUrl = "";
    paintProfile(SMILEY);
    return;
  }
  const blob = await res.blob();
  if (profileSavedUrl) URL.revokeObjectURL(profileSavedUrl);
  profileSavedUrl = URL.createObjectURL(blob);
  paintProfile(profileSavedUrl);
}

function squareJpeg(file) {
  // Crop to a 256px JPEG before upload. The server stores that file and can see it.
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(file);
    img.onload = () => {
      const size = 256;
      const canvas = document.createElement("canvas");
      canvas.width = size;
      canvas.height = size;
      const ctx = canvas.getContext("2d");
      const scale = Math.max(size / img.width, size / img.height);
      const w = img.width * scale;
      const h = img.height * scale;
      ctx.fillStyle = "#f5c518";
      ctx.fillRect(0, 0, size, size);
      ctx.drawImage(img, (size - w) / 2, (size - h) / 2, w, h);
      canvas.toBlob((blob) => {
        URL.revokeObjectURL(url);
        if (!blob) reject(new Error("That picture was not read."));
        else resolve(blob);
      }, "image/jpeg", 0.85);
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error("That picture was not read."));
    };
    img.src = url;
  });
}

