$("export-chats").addEventListener("click", async () => {
  const button = $("export-chats");
  const noteBox = $("export-note");
  noteBox.textContent = "Preparing the file…";
  button.disabled = true;
  try {
    const messages = [];
    const ordered = raw.slice().sort((a, b) => (a.ts - b.ts) || (a.seq - b.seq));
    for (const msg of ordered) {
      if (msg.deleted) continue;
      const row = {
        id: msg.id,
        chat: msg.box === "lobby" ? "lobby" : "dm",
        peer: msg.peer || "",
        sender: msg.sender || "",
        sent: msg.ts ? new Date(msg.ts * 1000).toISOString() : "",
        edited: msg.edited_ts ? new Date(msg.edited_ts * 1000).toISOString() : "",
      };
      if (msg.deleted) {
        row.removed = true;
        row.text = "";
      } else {
        const opened = await openMessage(msg);
        if (!opened || opened.locked || !opened.payload) {
          row.locked = true;
          row.text = "";
        } else {
          row.text = opened.payload.text || "";
          const file = opened.payload.file;
          if (file) {
            row.file = {
              name: file.name || "",
              mime: file.mime || "",
              kind: file.kind || "",
              size: file.size || 0,
            };
          }
        }
      }
      messages.push(row);
    }
    const doc = {
      app: "BranchChat",
      exported: new Date().toISOString(),
      username: (state.me && state.me.username) || "",
      note: "Text this device could open. Locked messages are marked. Removed messages have no text. File bytes and private keys are not included.",
      messages,
    };
    const blob = new Blob([JSON.stringify(doc, null, 2)], {type: "application/json"});
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "branch-chat-export-" + new Date().toISOString().slice(0, 10) + ".json";
    document.body.append(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(link.href), 1500);
    noteBox.textContent = "Download started.";
  } catch (err) {
    noteBox.textContent = err.message || "The file was not created.";
  } finally {
    button.disabled = false;
  }
});
