/* Sidebar collapse toggle, remembered per device. */
(() => {
  const root = document.documentElement;
  const label = (on) => { const b = document.getElementById("side-collapse"); if (b) { const t = on ? "Expand sidebar" : "Collapse sidebar"; b.title = t; b.setAttribute("aria-label", t); b.setAttribute("aria-expanded", on ? "false" : "true"); } };
  const set = (on) => { root.classList.toggle("side-collapsed", on); label(on); try { localStorage.setItem("bc-side-collapsed", on ? "1" : "0"); } catch (err) {} };
  try { if (localStorage.getItem("bc-side-collapsed") === "1") root.classList.add("side-collapsed"); } catch (err) {}
  label(root.classList.contains("side-collapsed"));
  document.getElementById("side-collapse")?.addEventListener("click", () => set(!root.classList.contains("side-collapsed")));
  document.getElementById("side-expand")?.addEventListener("click", () => set(false));
})();

/* Tap to show the icon credit bubble on touch screens; hides on tap elsewhere or after 3.5s. */
(() => {
  const icon = document.querySelector(".bc-icon");
  if (!icon) return;
  let timer = 0;
  const hide = () => { icon.classList.remove("tip-on"); clearTimeout(timer); };
  icon.addEventListener("click", (ev) => {
    ev.stopPropagation();
    if (icon.classList.contains("tip-on")) { hide(); return; }
    icon.classList.add("tip-on");
    clearTimeout(timer);
    timer = setTimeout(hide, 3500);
  });
  document.addEventListener("click", (ev) => { if (!icon.contains(ev.target)) hide(); });
})();

/* Keep the chat pinned to the newest message. Only a real user scroll (wheel, touch drag, keys, scrollbar) unpins it,
   so layout shifts from pictures, videos and voice clips loading can no longer leave the view stuck part-way up.
   New messages, chat switches, returning to the tab, rotating or resizing, and the keyboard opening all snap back to the bottom. */
(() => {
  const log = document.getElementById("log");
  if (!log) return;
  if ("scrollRestoration" in history) history.scrollRestoration = "manual";
  log.style.overflowAnchor = "none";
  let pinned = true, userAt = 0;
  const atBottom = () => log.scrollHeight - log.scrollTop - log.clientHeight < 120;
  const snap = () => { log.scrollTop = log.scrollHeight; };
  const toBottom = () => { if (pinned) snap(); };
  const settle = () => { if (!pinned) return; snap(); requestAnimationFrame(snap); setTimeout(toBottom, 120); setTimeout(toBottom, 400); setTimeout(toBottom, 1000); };
  const repin = () => { pinned = true; settle(); };
  const touched = () => { userAt = Date.now(); };
  document.addEventListener("bc-unpin", () => { pinned = false; touched(); });   // 26.10.11: jump to a replied-to message
  for (const ev of ["wheel", "touchmove", "pointerdown", "keydown"]) log.addEventListener(ev, touched, {passive: true});
  log.addEventListener("scroll", () => {
    if (Date.now() - userAt < 1200) pinned = atBottom();   // the person scrolled
    else if (pinned) snap();                               // layout moved under us: stay at the bottom
  }, {passive: true});
  log.addEventListener("load", toBottom, true);
  log.addEventListener("loadedmetadata", toBottom, true);
  const ro = "ResizeObserver" in window ? new ResizeObserver(toBottom) : null;
  if (ro) { ro.observe(log); for (const el of log.children) ro.observe(el); }
  new MutationObserver((muts) => {
    let added = false;
    for (const m of muts) {
      for (const n of m.addedNodes) if (n.nodeType === 1) { added = true; if (ro && n.parentNode === log) ro.observe(n); }
      // 26.10.2 perf: stop watching rows that left the list. Before, every rebuild added ~400 new watches and never
      // dropped the old ones, so removed rows stayed in memory and each resize check walked an ever-growing list.
      if (ro && m.target === log) for (const n of m.removedNodes) if (n.nodeType === 1 && n.parentNode !== log) ro.unobserve(n);
    }
    // A new message snaps to the bottom unless the person is actively reading older messages right now.
    if (added && Date.now() - userAt > 4000) pinned = true;
    requestAnimationFrame(settle);
  }).observe(log, {childList: true, subtree: true});
  window.addEventListener("load", repin);
  window.addEventListener("resize", () => requestAnimationFrame(toBottom));
  window.visualViewport?.addEventListener("resize", () => requestAnimationFrame(toBottom));
  document.addEventListener("visibilitychange", () => { if (!document.hidden) repin(); });
  window.addEventListener("pageshow", repin);
  document.getElementById("sidebar")?.addEventListener("click", (ev) => {
    if (ev.target.closest(".person, #lobby-row")) { pinned = true; setTimeout(settle, 50); }
  });
  document.getElementById("send")?.addEventListener("click", () => setTimeout(repin, 30));
  document.querySelector("#composer, form#compose, .composer")?.addEventListener("submit", () => setTimeout(repin, 30));
})();


/* Per-chat transparency slider: how see-through the chat area is over its background. Saved per chat on this device. */
(() => {
  const slider = document.getElementById("transp");
  const out = document.getElementById("transp-val");
  if (!slider) return;
  const root = document.documentElement;
  // Oct 2026: with the background now behind the whole site, the chat pane starts nearly clear (85 %) over a picture.
  // New key (bc-transp2) so everyone starts from the new default; the old per-chat bc-transp values are left unused.
  const defaults = {upload: 85, preset: 85, none: 64};
  const key = () => "bc-transp2:" + bgStoreKey();
  const apply = () => {
    const kind = root.dataset.chatbg || "none";
    let val = NaN;
    try { val = parseInt(localStorage.getItem(key() + ":" + kind), 10); } catch (err) {}
    if (!Number.isFinite(val)) val = defaults[kind] ?? 50;
    slider.value = String(val);
    out.textContent = val + "%";
    root.style.setProperty("--transp", val + "%");
    root.style.setProperty("--transp-n", String(val / 100));
    root.dataset.transp = "1";
  };
  slider.addEventListener("input", () => {
    const val = parseInt(slider.value, 10);
    out.textContent = val + "%";
    root.style.setProperty("--transp", val + "%");
    root.style.setProperty("--transp-n", String(val / 100));
    try { localStorage.setItem(key() + ":" + (root.dataset.chatbg || "none"), String(val)); } catch (err) {}
  });
  new MutationObserver(apply).observe(root, {attributes: true, attributeFilter: ["data-chatbg"]});
  document.getElementById("sidebar")?.addEventListener("click", () => setTimeout(apply, 120));
  apply();
})();

/* Tap or click outside any pop-up dialog (on its backdrop) to close it, same as Cancel.
   26.10.5: the friend profile card closes on the click (after the finger lifts), not on finger-down, so the rest
   of the tap stays on the dim area instead of landing on the chat that appears underneath. Other dialogs keep
   their old finger-down close here for now (changing every dialog is a separate, wider fix). */
const backdropHit = (dlg, ev) => {
  const r = dlg.getBoundingClientRect();
  return !(ev.clientX >= r.left && ev.clientX <= r.right && ev.clientY >= r.top && ev.clientY <= r.bottom);
};
let cardDownOutside = false;
document.addEventListener("pointerdown", (ev) => {
  const dlg = ev.target;
  if (!(dlg instanceof HTMLDialogElement) || !dlg.open) return;
  if (dlg.id === "friend-card") { cardDownOutside = backdropHit(dlg, ev); if (cardDownOutside) ev.preventDefault(); return; }
  if (backdropHit(dlg, ev)) { ev.preventDefault(); dlg.close(); }
});
document.addEventListener("click", (ev) => {
  const dlg = ev.target;
  if (!(dlg instanceof HTMLDialogElement) || dlg.id !== "friend-card" || !dlg.open) return;
  if (cardDownOutside && backdropHit(dlg, ev)) { ev.preventDefault(); ev.stopPropagation(); dlg.close(); }
  cardDownOutside = false;
});

/* Circled X in the top-right corner of every pop-up. Plain "Close" buttons are retired in favor of it. */
(() => {
  const make = (onClose) => {
    const b = document.createElement("button");
    b.type = "button";
    b.className = "x-close";
    b.setAttribute("aria-label", "Close");
    b.title = "Close";
    b.innerHTML = '<svg viewBox="0 0 16 16" width="12" height="12" aria-hidden="true"><path d="M3.5 3.5l9 9M12.5 3.5l-9 9" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" fill="none"/></svg>';
    b.addEventListener("click", (ev) => { ev.stopPropagation(); onClose(); });
    return b;
  };
  document.querySelectorAll("dialog").forEach((dlg) => {
    if (dlg.querySelector(":scope > .x-close")) return;
    if (dlg.classList.contains("bubble-confirm")) return;   // the speech bubble has its own X button
    dlg.prepend(make(() => dlg.close()));
    dlg.querySelectorAll("button").forEach((btn) => {
      if (!btn.classList.contains("x-close") && btn.textContent.trim().toLowerCase() === "close") btn.hidden = true;
    });
  });
  const menu = document.getElementById("app-menu");
  if (menu && !menu.querySelector(":scope > .x-close")) menu.prepend(make(() => closeMenu()));
  const prof = document.getElementById("profile-pop");
  if (prof && !prof.querySelector(":scope > .x-close")) prof.prepend(make(() => closeProfile()));
})();

