    if (tail) sendPart(tail, [{transform: "rotate(0)"}, {transform: "rotate(14deg)"}, {transform: "rotate(0)"}], {duration: sendT(300), iterations: 3, fill: "none"});
    const mr = mpt.getBoundingClientRect();
    sendWhoosh(1.1, 600, 2200, .08);
    let n = 0; const tw = [1568, 1760, 2093, 2349, 1976];
    await sendTiles(bub, {from: () => ({x: mr.left + mr.width / 2, y: mr.top + mr.height / 2}), order: "center", fly: 620, wave: 520, small: 20, spin: 140, scatter: 18, arc: -70,
      pal: ["#ffd36b", "#ff9a3d", "#7ff0d8", "#ffffff", "#ffb3e6"], onLand: (k, N) => { if (k % Math.max(1, Math.round(N / 6)) === 0) sendBlip([[tw[n++ % tw.length], 0, .12, "sine", .05]]); }});
    sendPart(jaw, [{transform: "translateY(18%)"}, {transform: "translateY(0)"}], {duration: sendT(140)});
    sendBlip([[784, 0, .14, "sine", .08], [988, .12, .14, "sine", .08], [1175, .24, .26, "sine", .07]]);   // happy little chime
    sendPart(S.fig, [{transform: "translateY(0)"}, {transform: "translateY(-14%)"}, {transform: "translateY(0)"}, {transform: "translateY(-6%)"}, {transform: "translateY(0)"}], {duration: sendT(520), fill: "none"});
    await sendWait(sendT(540));
