  const n = document.createElement("p"); n.className = "sendanim-ask-note"; n.textContent = "You can change this any time in the menu under Send animations.";
  const row = document.createElement("div"); row.className = "sendanim-ask-btns";
  const keep = document.createElement("button"); keep.type = "button"; keep.className = "sendanim-keep"; keep.textContent = "Keep them";
  const off = document.createElement("button"); off.type = "button"; off.className = "sendanim-off"; off.textContent = "Turn off";
