  const ids = room.box === "lobby" ? [] : pinIds();
  const k = JSON.stringify([roomKey(room), ids, ids.map((id) => !!fwdOpened(id))]);
  if (k === pinKey) return; pinKey = k;
  bar.hidden = !ids.length;
