var chatListView = "main";   // "main" or "archived" (the archived chats swap into the same panel)
var LOBBY_ICON_SVG = '<svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path fill="currentColor" d="M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20zm6.9 6h-2.9a15.7 15.7 0 0 0-1.4-3.6A8 8 0 0 1 18.9 8zM12 4c.8 1.2 1.5 2.5 1.9 4h-3.8c.4-1.5 1.1-2.8 1.9-4zM4.3 14a8.2 8.2 0 0 1 0-4h3.4a16.5 16.5 0 0 0 0 4H4.3zm.8 2h2.9c.3 1.3.8 2.5 1.4 3.6A8 8 0 0 1 5.1 16zM8 8H5.1a8 8 0 0 1 4.3-3.6C8.8 5.5 8.3 6.7 8 8zm4 12c-.8-1.2-1.5-2.5-1.9-4h3.8c-.4 1.5-1.1 2.8-1.9 4zm2.3-6H9.7a14.7 14.7 0 0 1 0-4h4.6a14.7 14.7 0 0 1 0 4zm.3 5.6c.6-1.1 1.1-2.3 1.4-3.6h2.9a8 8 0 0 1-4.3 3.6zm1.7-5.6a16.5 16.5 0 0 0 0-4h3.4a8.2 8.2 0 0 1 0 4h-3.4z"/></svg>';
var PIN_SVG = '<svg class="row-pin" viewBox="0 0 24 24" width="13" height="13" aria-label="Pinned" role="img"><path fill="currentColor" d="M16 3l5 5-2 1-3 3 1 5-2 2-4-4-5 5-1-1 5-5-4-4 2-2 5 1 3-3z"/></svg>';
var ARCHIVE_SVG = '<svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path fill="currentColor" d="M3 4h18v4H3V4zm1 5h16v11H4V9zm5 3v2h6v-2H9z"/></svg>';
var GRIP_SVG = '<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true"><g fill="currentColor"><circle cx="9" cy="6" r="1.6"/><circle cx="15" cy="6" r="1.6"/><circle cx="9" cy="12" r="1.6"/><circle cx="15" cy="12" r="1.6"/><circle cx="9" cy="18" r="1.6"/><circle cx="15" cy="18" r="1.6"/></g></svg>';

function chatListPrefs() {
  const c = (state && state.chatlist) || {};
  const list = (v) => (Array.isArray(v) ? v.filter((k) => typeof k === "string") : []);
  return {pins: list(c.pins), order: list(c.order), archived: list(c.archived)};
}
function chatListKey(key) { return typeof key === "string" && key.indexOf("dm:") === 0 ? key.toLowerCase() : key; }
function chatKeyUnread(key) { return unreadBy.get(key) || 0; }

function decorateChatRow(el, key, block, pinned) {
  el.dataset.key = key;
  el.dataset.block = block;
  el.classList.add("chat-row");
  el.classList.toggle("is-pinned", !!pinned);
  const top = el.querySelector(".row-top");
  if (top && pinned && !top.querySelector(".row-pin")) {
    const t = top.querySelector(".row-time");
    t ? t.insertAdjacentHTML("beforebegin", PIN_SVG) : top.insertAdjacentHTML("beforeend", PIN_SVG);
  }
  if (block !== "archived" && !el.querySelector(".drag-handle")) {
    const h = document.createElement("span");
    h.className = "drag-handle";
    h.setAttribute("aria-hidden", "true");
    h.title = "Drag to reorder";
    h.innerHTML = GRIP_SVG;
    el.append(h);
  }
  return el;
}

function archivedEntryRow(arch) {
  // The last row of the list, styled like a chat. Tapping it swaps the panel to the archived chats.
  const b = document.createElement("button");
  b.type = "button";
  b.id = "archived-row";
  b.className = "person chat-row archived-row";
  const pic = document.createElement("span");
  pic.className = "pfp arch-pic";
  pic.innerHTML = ARCHIVE_SVG;
  const nm = document.createElement("span");
  nm.textContent = "Archived Chats";
  const unread = arch.reduce((n, x) => n + chatKeyUnread(x.key), 0);
  b.append(pic, chatRowMain(nm, null, arch.length + (arch.length === 1 ? " chat" : " chats"), unreadMark(unread), "", false));
  b.addEventListener("click", () => { if (rowTapOk()) openArchivedView(); });
  return b;
}

function setChatListView(v) {
  if (chatListView === v) return;
  chatListView = v;
  paintKey = "";
  maybeRender();
  const p = $("people");
  if (p) p.scrollTop = 0;
  if (v === "archived") { const back = $("arch-back"); if (back) try { back.focus({preventScroll: true}); } catch (err) {} }
}
function openArchivedView() {
  try { history.pushState({bc: "archived"}, "", location.href); } catch (err) {}
  setChatListView("archived");
}
function closeArchivedView() {
  if (chatListView !== "archived") return;
  if (navState() === "archived") { try { history.back(); } catch (err) {} }   // popstate below finishes it
  setChatListView("main");
}
$("arch-back").addEventListener("click", closeArchivedView);
window.addEventListener("popstate", () => { if (chatListView === "archived" && navState() !== "archived" && navState() !== "chat") setChatListView("main"); });
document.addEventListener("keydown", (ev) => {
  if (ev.key !== "Escape" || chatListView !== "archived" || document.querySelector("dialog[open]")) return;
  if (!document.documentElement.classList.contains("no-chat") && !$("sidebar").contains(document.activeElement)) return;
  ev.preventDefault();
  closeArchivedView();
});

async function chatListSave(body, optimistic) {
  // Update the list right away, then save; the server's answer (or the next sync) is the truth.
  const before = state.chatlist;
  if (optimistic) { state.chatlist = optimistic; paintKey = ""; maybeRender(); }
  try {
    const data = await post("/api/chats/list", body);
    if (data && data.chatlist) { state.chatlist = data.chatlist; paintKey = ""; maybeRender(); }
  } catch (err) {
    state.chatlist = before; paintKey = ""; maybeRender();
    if (typeof toast === "function") toast(err.message || "That did not save. Try again.");
  }
}
function chatListAct(op, key) {
  key = chatListKey(key);
  const p = chatListPrefs();
  const drop = (a) => a.filter((k) => k !== key);
  if (op === "pin") { p.pins = [key].concat(drop(p.pins)); p.archived = drop(p.archived); }
  else if (op === "unpin") p.pins = drop(p.pins);
  else if (op === "archive") { if (!p.archived.includes(key)) p.archived.push(key); p.pins = drop(p.pins); }
  else if (op === "unarchive") p.archived = drop(p.archived);
  chatListSave({op, chat: key}, p);
}
function chatListReorder(block, keys) {
  const p = chatListPrefs();
  if (block === "pinned") { keys = keys.map(chatListKey); p.pins = keys.slice(); chatListSave({op: "order", pins: keys}, p); return; }
  // Save the whole visible "chats" order: anything dragged becomes part of your order from now on.
  keys = keys.map(chatListKey);
  p.order = keys.slice();
  chatListSave({op: "order", order: keys}, p);
}

// The long-press / right-click menu for a chat row: Pin, Archive, Mute.
function chatMenuSheet() {
  let d = $("chat-sheet");
  if (d) return d;
  d = document.createElement("dialog");
  d.id = "chat-sheet";
  d.className = "chat-sheet";
  d.innerHTML = '<h3 id="chat-sheet-title"></h3><div class="chat-sheet-acts"></div><button type="button" class="chat-sheet-cancel">Cancel</button>';
  d.addEventListener("click", (ev) => { if (ev.target === d) d.close(); });
  d.querySelector(".chat-sheet-cancel").addEventListener("click", () => d.close());
  document.body.append(d);
  return d;
}
function openChatMenu(key) {
  if (!roomFromKey(key)) return;
  const p = chatListPrefs(), ck = chatListKey(key);
  const pinned = p.pins.includes(ck), archived = p.archived.includes(ck), muted = chatIsMuted(key);
  const d = chatMenuSheet();
  $("chat-sheet-title").textContent = muteTitle(key);
  const acts = d.querySelector(".chat-sheet-acts");
  acts.replaceChildren();
  const add = (icon, label, fn) => {
    const b = document.createElement("button");
    b.type = "button";
    b.innerHTML = icon;
    b.append(document.createTextNode(label));
    b.addEventListener("click", () => { d.close(); fn(); });
    acts.append(b);
  };
  if (!archived) add(PIN_SVG.replace('width="13" height="13"', 'width="20" height="20"'), pinned ? "Unpin" : "Pin to top", () => chatListAct(pinned ? "unpin" : "pin", key));
  add(ARCHIVE_SVG, archived ? "Unarchive" : "Archive", () => chatListAct(archived ? "unarchive" : "archive", key));
  add(muted ? BELL_OFF_SVG.replace(/width="15" height="15"/, 'width="20" height="20"') : BELL_SVG, muted ? "Mute settings…" : "Mute…", () => openMute(key));
  if (!d.open) d.showModal();
}

// Optional: a new message in an archived chat brings it back (off by default, see ARCHIVE_WAKES_ON_MESSAGE).
function archiveWakeCheck() {
  if (!ARCHIVE_WAKES_ON_MESSAGE) return;
  const arch = new Set(chatListPrefs().archived);
  for (const [key, n] of unreadBy) if (n > 0 && arch.has(chatListKey(key))) chatListAct("unarchive", key);
}

/* Drag to reorder inside the ONE scroll container (#people): grab the grip on the right of a row (mouse, pen or
   touch). The grip has touch-action:none, so dragging it never scrolls the page; the rest of the row scrolls the
   list normally. Pinned chats reorder among themselves; the other chats among themselves. Auto-scrolls near the edges. */
(function initChatDrag() {
  const box = document.getElementById("people");
  if (!box) return;
  let d = null;
  const rowsOf = (block) => [...box.querySelectorAll('.chat-row[data-block="' + block + '"]')].filter((r) => r.offsetParent);
  function layout() {
    const dy = d.y - d.startY + (box.scrollTop - d.startScroll);
    d.row.style.transform = "translateY(" + dy + "px)";
    const mid = d.rect.top + d.rect.height / 2 + dy;
    let idx = d.from;
    d.others.forEach((o) => { o.style.transform = ""; });
    for (let i = 0; i < d.rows.length; i++) {
      if (i === d.from) continue;
      const c = d.mids[i];   // start-of-drag layout coords, same frame as `mid`
      if (i > d.from && mid > c) idx = i;
      if (i < d.from && mid < c && idx === d.from) idx = i;
    }
    if (idx < d.from) for (let i = idx; i < d.from; i++) d.rows[i].style.transform = "translateY(" + d.h + "px)";
    if (idx > d.from) for (let i = d.from + 1; i <= idx; i++) d.rows[i].style.transform = "translateY(" + -d.h + "px)";
    d.to = idx;
  }
  function tick() {
    if (!d) return;
    const r = box.getBoundingClientRect(), edge = 48;
    let v = 0;
    if (d.y < r.top + edge) v = -Math.ceil((r.top + edge - d.y) / 4);
    else if (d.y > r.bottom - edge) v = Math.ceil((d.y - (r.bottom - edge)) / 4);
    if (v) { box.scrollTop += v; layout(); }
    d.raf = requestAnimationFrame(tick);
  }
  box.addEventListener("pointerdown", (ev) => {
    const h = ev.target instanceof Element && ev.target.closest(".drag-handle");
    if (!h || (ev.button && ev.button !== 0)) return;
    const row = h.closest(".chat-row");
    if (!row || !row.dataset.block || row.dataset.block === "archived") return;
    ev.preventDefault();
    const rows = rowsOf(row.dataset.block);
    const startScroll = box.scrollTop;
    d = { row, rows, from: rows.indexOf(row), to: rows.indexOf(row), others: rows.filter((r) => r !== row),
      startY: ev.clientY, y: ev.clientY, startScroll, rect: row.getBoundingClientRect(),
      mids: rows.map((r) => { const b = r.getBoundingClientRect(); return b.top + b.height / 2; }), id: ev.pointerId };
    const st = getComputedStyle(box);
    d.h = d.rect.height + (parseFloat(st.rowGap || st.gap) || 0);
    try { h.setPointerCapture(ev.pointerId); } catch (e) {}
    row.classList.add("dragging");
    d.others.forEach((o) => o.classList.add("drag-shift"));
    document.documentElement.classList.add("chat-dragging");
    d.raf = requestAnimationFrame(tick);
  });
  function move(ev) { if (!d || ev.pointerId !== d.id) return; ev.preventDefault(); d.y = ev.clientY; layout(); }
  function end(ev) {
    if (!d || ev.pointerId !== d.id) return;
    const { row, rows, from, to } = d;
    cancelAnimationFrame(d.raf);
    rows.forEach((r) => { r.style.transform = ""; r.classList.remove("drag-shift", "dragging"); });
    document.documentElement.classList.remove("chat-dragging");
    d = null;
    window.chatDragEndedAt = Date.now();
    if (ev.type === "pointercancel" || from === to) return;
    const keys = rows.map((r) => r.dataset.key);
    const [k] = keys.splice(from, 1); keys.splice(to, 0, k);
    const ref = to > from ? rows[to].nextSibling : rows[to];
    row.parentNode.insertBefore(row, ref);
    chatListReorder(row.dataset.block, keys);
  }
  box.addEventListener("pointermove", move, { passive: false });
  box.addEventListener("pointerup", end);
  box.addEventListener("pointercancel", end);
})();

/* chatlist-pin-reorder: compact panel footer (Variant B, picked by Luke).
   Slim profile pill, plus a separate subtle "+" button beside it that opens a small menu (New group, Add friend).
   ?foot=classic (remembered on this device) brings back the old footer for comparison; ?foot=b returns to this one. */
var FOOTER_VARIANT = "b";
(function initCompactFooter() {
  const root = document.documentElement, bar = document.getElementById("me-bar"), gear = document.getElementById("me-gear");
  const acts = document.getElementById("side-actions"), dock = document.getElementById("me-dock");
  if (!bar || !gear || !acts || !dock) return;
  let v = FOOTER_VARIANT;
  try { const q = new URLSearchParams(location.search).get("foot"); if (q) localStorage.setItem("bc-foot", q); v = localStorage.getItem("bc-foot") || v; } catch (e) {}
  if (v !== "b") return;   // "classic": leave the old footer alone
  root.classList.add("foot-b");
  const btns = [...acts.querySelectorAll(".side-act")];
  const plus = document.createElement("button");
  plus.type = "button"; plus.id = "foot-plus"; plus.title = "New group or add friend";
  plus.setAttribute("aria-label", "New group or add friend"); plus.setAttribute("aria-haspopup", "menu"); plus.setAttribute("aria-expanded", "false");
  plus.innerHTML = '<svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true"><path fill="currentColor" d="M11 5h2v6h6v2h-6v6h-2v-6H5v-2h6z"/></svg>';
  const menu = document.createElement("div");
  menu.id = "foot-menu"; menu.setAttribute("role", "menu"); menu.hidden = true;
  for (const b of btns) { b.setAttribute("role", "menuitem"); menu.append(b); }
  acts.hidden = true;
  bar.after(plus); dock.append(menu);   // + sits outside the profile pill, beside it
  const show = (on) => { menu.hidden = !on; plus.setAttribute("aria-expanded", on ? "true" : "false"); };
  plus.addEventListener("click", (ev) => { ev.stopPropagation(); show(menu.hidden); });
  menu.addEventListener("click", () => show(false));
  document.addEventListener("click", (ev) => { if (!menu.hidden && !menu.contains(ev.target)) show(false); });
  document.addEventListener("keydown", (ev) => { if (ev.key === "Escape" && !menu.hidden) show(false); });
})();
